// Visual explainers for the System Design roadmap. Schema: CONTRIBUTING.md → "Visuals".
'use strict';

// ===== Module 2: Scalability ===================================================

registerDiagram({
  id: 'sd-scale-up-vs-out',
  roadmap: 'system-design', module: 2, topic: 'Vertical vs Horizontal Scaling',
  kind: 'graph',
  title: 'Scale up the box, then scale out the stateless tier',
  desc: 'One server is the simplest system you can build. Watch it grow vertically until it hits cost and availability limits, then see how a load balancer and identical stateless replicas take over, while the database keeps scaling up.',
  groups: [
    { id: 'tier', label: 'Stateless app tier (N+1)', x: 4, y: 0, w: 1, h: 4, color: 'blue' },
  ],
  nodes: [
    { id: 'users', label: 'Users', sub: '10K → 1M req/day', icon: '👥', x: 0, y: 1.5, color: 'gray', info: 'Traffic grows over time. Every scaling decision starts from a number: peak QPS, data size and the availability target.' },
    { id: 'lb', label: 'Load balancer', sub: 'health checks', x: 2, y: 1.5, color: 'teal', enter: 4, info: 'Spreads requests across healthy replicas and removes failed ones after a few failed health checks. Run it as a managed service or an active-passive pair so it is not the new single point of failure.' },
    { id: 'app1', label: 'App replica 1', sub: '4 vCPU', x: 4, y: 0.5, color: 'blue', enter: 4, info: 'Identical, interchangeable copies of the app. Adding one adds roughly linear capacity, provided they share nothing that needs coordination on every request.' },
    { id: 'app2', label: 'App replica 2', sub: '4 vCPU', x: 4, y: 1.5, color: 'blue', enter: 4, exit: 6, info: 'This replica fails in step 6. Because no session or file lives only on it, users notice at most one retried request.' },
    { id: 'app3', label: 'App replica 3', sub: '4 vCPU', x: 4, y: 2.5, color: 'blue', enter: 4, info: 'Autoscaling adds or removes replicas like this one from CPU or request-rate metrics.' },
    { id: 'box', label: 'Primary server', sub: 'app+DB, then DB only', x: 6, y: 1.5, shape: 'db', color: 'green', info: 'Starts as one VM running app and database. Later it keeps only the database, scaled up as far as is economical: a large NVMe instance running Postgres can serve tens of thousands of simple queries per second.' },
  ],
  edges: [
    { from: 'users', to: 'lb', label: 'HTTPS' },
    { from: 'lb', to: 'app1' }, { from: 'lb', to: 'app2' }, { from: 'lb', to: 'app3' },
    { from: 'app1', to: 'box' }, { from: 'app2', to: 'box', label: 'SQL' }, { from: 'app3', to: 'box' },
  ],
  steps: [
    { caption: 'Day one: a single server runs the app and the database. There is no network between them, transactions are local and deploys are trivial. This is the right design until the numbers say otherwise.', flows: [{ from: 'users', to: 'box', label: 'request' }] },
    { caption: 'Scale up (vertical): move to a bigger machine, say 8 to 96 vCPUs. No code changes, but the price grows faster than the capacity, there is a hard ceiling, and resizing usually means a restart.', active: ['box'] },
    { caption: 'The real problem is availability: one box is a single point of failure. A kernel patch, a disk failure or an AZ outage takes the whole product down.', flows: [{ from: 'box', to: 'users', label: '503 outage', color: 'red' }] },
    { caption: 'Scale out (horizontal): put a load balancer in front of several identical app replicas and move the database to its own box. Capacity now grows by adding commodity nodes while traffic keeps flowing.', flows: [{ from: 'users', to: 'lb', label: 'request' }, { from: 'lb', to: 'app1' }, { from: 'lb', to: 'app3' }] },
    { caption: 'Any replica can serve any request only if the replicas are stateless: sessions in Redis or a signed token, files in object storage, background work in a queue. Local state is what forces sticky sessions.', flows: [{ from: 'lb', to: 'app2', label: 'any replica' }, { from: 'app2', to: 'box', label: 'shared state' }] },
    { caption: 'Replica 2 dies. The load balancer marks it unhealthy after a few failed checks and the other replicas absorb its share. Plan N+1 capacity so the survivors are not overloaded.', flows: [{ from: 'lb', to: 'app1' }, { from: 'lb', to: 'app3' }], active: ['tier'] },
    { caption: 'The stateful database is now the bottleneck and still scales vertically. Next come read replicas, caching and finally sharding. Linear scale-out holds only while nodes need not coordinate on every request.', flows: [{ from: 'app1', to: 'box' }, { from: 'app3', to: 'box' }], active: ['box'] },
  ],
});

// ===== Module 3: Caching =======================================================

registerDiagram({
  id: 'sd-cache-patterns',
  roadmap: 'system-design', module: 3, topic: 'Caching Patterns: Aside, Read-Through, Write-Through, Write-Behind, Refresh-Ahead',
  kind: 'graph',
  title: 'Who fills the cache, and when: five patterns on one picture',
  desc: 'The same three boxes (app, cache, database) behave very differently depending on who reads and writes the cache. Step through cache-aside, write-through, write-behind, write-around and refresh-ahead.',
  nodes: [
    { id: 'client', label: 'Client', icon: '💻', x: 0, y: 1, color: 'gray', info: 'Sends reads and writes to the service. It never talks to the cache or the database directly.' },
    { id: 'app', label: 'App service', sub: 'owns cache logic', x: 2, y: 1, color: 'blue', info: 'In cache-aside the application code decides when to read, fill and delete cache entries. In read-through or write-through a cache library or provider does it for the app.' },
    { id: 'cache', label: 'Redis', sub: '~0.5 ms, TTL keys', x: 4, y: 0, shape: 'db', color: 'red', info: 'An in-memory cache shared by all replicas. A cache-aside cache is disposable: if it is down, the app is slower but still correct.' },
    { id: 'db', label: 'Database', sub: 'source of truth', x: 4, y: 2, shape: 'db', color: 'green', info: 'Always the authority. Every cache pattern is a trade-off between how stale the cache may be and how much latency or risk the write path takes on.' },
  ],
  edges: [
    { from: 'client', to: 'app', both: true },
    { from: 'app', to: 'cache', both: true, label: 'GET / SET / DEL' },
    { from: 'app', to: 'db', both: true, label: 'SQL' },
    { from: 'cache', to: 'db', label: 'sync or async' },
  ],
  steps: [
    { caption: 'Cache-aside read, hit: the app checks Redis first and answers in about half a millisecond. With a 90-95% hit ratio the database sees only a small fraction of reads.', flows: [{ from: 'client', to: 'app', label: 'GET /user/42' }, { from: 'app', to: 'cache', label: 'GET user:42' }, { from: 'cache', to: 'app', label: 'hit', color: 'green' }] },
    { caption: 'Cache-aside read, miss: three trips. The app reads the database, then stores the value with a TTL so the next reader hits. Only data somebody actually asked for is cached.', flows: [{ from: 'cache', to: 'app', label: 'miss', color: 'red' }, { from: 'app', to: 'db', label: 'SELECT' }, { from: 'app', to: 'cache', label: 'SET ttl=300' }] },
    { caption: 'Cache-aside write: update the database, then DELETE the key rather than overwrite it. Two concurrent writers updating the cache could land in the opposite order to the database; a delete is idempotent.', flows: [{ from: 'app', to: 'db', label: 'UPDATE' }, { from: 'app', to: 'cache', label: 'DEL user:42', color: 'orange' }] },
    { caption: 'Write-through: the write goes to the cache, which writes the database synchronously before acknowledging. Written keys are always fresh, but every write pays both latencies and may cache data nobody reads.', flows: [{ from: 'app', to: 'cache', label: 'SET' }, { from: 'cache', to: 'db', label: 'sync write' }] },
    { caption: 'Write-behind: the cache acknowledges at once and flushes to the database later in batches. Writes are very fast and bursts are absorbed, but anything not yet flushed is lost if the cache node dies. Use it for counters and analytics.', flows: [{ from: 'app', to: 'cache', label: 'INCR views' }, { from: 'cache', to: 'db', label: 'batch flush', color: 'orange' }] },
    { caption: 'Write-around: writes go straight to the database and the cache fills only on read. It keeps write-once data such as logs or uploads from evicting hot entries, at the cost of a miss on the first read.', flows: [{ from: 'app', to: 'db', label: 'INSERT' }], active: ['cache'] },
    { caption: 'Refresh-ahead: hot keys are reloaded shortly before their TTL expires, so readers never see the miss latency. Wrong predictions waste work. The default answer in interviews is cache-aside with TTL and delete-on-write.', flows: [{ from: 'cache', to: 'db', label: 'reload hot key' }] },
  ],
});

registerDiagram({
  id: 'sd-cache-stale-set-race',
  roadmap: 'system-design', module: 3, topic: 'Cache Invalidation & Consistency',
  kind: 'sequence',
  title: 'The cache-aside stale-set race, and how leases fix it',
  desc: 'Delete-on-write still leaves a window where a slow reader puts an old value back into the cache. Follow the interleaving that causes it, then the lease mechanism Facebook added to memcache to reject the late write.',
  actors: [
    { id: 'ra', label: 'Reader A', sub: 'slow request', icon: '🐢', color: 'blue', info: 'A request that misses the cache and is slowed down between reading the database and filling the cache, for example by a GC pause or a slow network.' },
    { id: 'cache', label: 'Cache', sub: 'memcache / Redis', color: 'red', info: 'Holds derived copies. It has no idea which copy is newer unless the protocol gives it a way to tell, such as a lease token or a version.' },
    { id: 'db', label: 'Database', sub: 'source of truth', color: 'green', info: 'Has the correct value, v2, the whole time. The bug is purely in the cache.' },
    { id: 'wb', label: 'Writer B', sub: 'profile update', icon: '✍️', color: 'orange', info: 'Follows the textbook cache-aside write: update the database, then delete the cache key.' },
  ],
  steps: [
    { section: 'The race' },
    { from: 'ra', to: 'cache', label: 'GET user:42', caption: 'Reader A looks up user 42 in the cache.' },
    { from: 'cache', to: 'ra', label: 'miss', reply: true, caption: 'The key is not cached, so A will load it from the database itself.' },
    { from: 'ra', to: 'db', label: 'SELECT user 42', caption: 'A reads the row from the database.' },
    { from: 'db', to: 'ra', label: 'v1', reply: true, caption: 'A gets v1 back. A is now delayed before it writes to the cache, for example by a GC pause.' },
    { from: 'wb', to: 'db', label: 'UPDATE → v2', caption: 'Meanwhile Writer B updates the row to v2 and commits.' },
    { from: 'wb', to: 'cache', label: 'DEL user:42', caption: 'B deletes the cache key, exactly as cache-aside prescribes. The key was not there, so the delete does nothing.' },
    { from: 'ra', to: 'cache', label: 'SET user:42 = v1', caption: 'A wakes up and writes the stale v1 it read earlier. The database says v2, but the cache now says v1.' },
    { from: 'cache', to: 'cache', label: 'stale until TTL', caption: 'Every reader gets v1 until the TTL expires. A short TTL bounds the damage; it does not prevent it.' },
    { section: 'Fix: leases (memcache)' },
    { from: 'ra', to: 'cache', label: 'GET → miss + lease L1', caption: 'On a miss the cache hands A a lease token, L1. Only the holder of a valid lease may fill this key.' },
    { from: 'wb', to: 'cache', label: 'DEL (voids lease L1)', caption: 'B deletes the key after writing v2. The delete also invalidates every outstanding lease for that key.' },
    { from: 'ra', to: 'cache', label: 'SET v1 with lease L1', caption: 'A tries to store its stale v1 with lease L1.' },
    { from: 'cache', to: 'ra', label: 'rejected: lease void', reply: true, caption: 'The cache rejects the late write. The next reader misses, gets a fresh lease and loads v2. Leases also throttle stampedes: one lease per key every few seconds. Alternatives: versioned keys with CAS, delayed double delete.' },
  ],
});

registerDiagram({
  id: 'sd-cache-stampede',
  roadmap: 'system-design', module: 3, topic: 'Cache Stampede, Thundering Herd & Hot Keys',
  kind: 'graph',
  title: 'A hot key expires: stampede, then three layers of defence',
  desc: 'When a key that serves thousands of requests per second expires, every request misses at the same moment. Watch the database get flattened, then add singleflight, a lock with stale serving, jittered TTLs and hot-key replicas.',
  groups: [
    { id: 'pods', label: 'App pods', x: 0, y: 1, w: 1, h: 3, color: 'blue' },
    { id: 'redis', label: 'Redis', x: 3, y: 0, w: 2, h: 1, color: 'red' },
  ],
  nodes: [
    { id: 'pa', label: 'Pod A', sub: '1,000 goroutines', x: 0, y: 1, color: 'blue', info: 'Each pod runs many concurrent requests for the same hot key. singleflight (golang.org/x/sync/singleflight) makes them share one in-flight load.' },
    { id: 'pb', label: 'Pod B', sub: '1,000 goroutines', x: 0, y: 2, color: 'blue', info: 'singleflight is per process: with N pods you still get N loads, which is why a distributed lock or lease is the second layer.' },
    { id: 'pc', label: 'Pod C', sub: '1,000 goroutines', x: 0, y: 3, color: 'blue', info: 'Can also keep a tiny in-process L1 cache with a TTL of a few seconds for the hottest keys, so most requests never leave the pod.' },
    { id: 'hot', label: 'product:99', sub: 'hot key, soft TTL', x: 3, y: 0, color: 'red', info: 'Store the value with a soft expiry inside the payload and a longer hard TTL on the key. After the soft expiry the old value can still be served while one caller refreshes it.' },
    { id: 'reps', label: 'product:99#1..#8', sub: 'hot-key copies', x: 4, y: 0, color: 'red', enter: 7, info: 'A single Redis shard does roughly 100K+ simple ops/s on one core. Copies on different shards spread the load: read a random copy, write all copies.' },
    { id: 'lock', label: 'lock:product:99', sub: 'SET NX PX 5000', x: 3, y: 4, color: 'orange', info: 'A short-lived lock so that only one caller in the whole fleet recomputes. The expiry (PX) guarantees it is released if the holder crashes.' },
    { id: 'db', label: 'Database', sub: 'expensive query', x: 6, y: 2, shape: 'db', color: 'green', info: 'The query behind this key is expensive (joins, aggregation). The database can handle a few loads per second, not thousands at once.' },
  ],
  edges: [
    { from: 'pa', to: 'hot' }, { from: 'pb', to: 'hot' }, { from: 'pc', to: 'hot' },
    { from: 'pa', to: 'db', dashed: true }, { from: 'pb', to: 'db', dashed: true }, { from: 'pc', to: 'db', dashed: true },
  ],
  steps: [
    { caption: 'Normal operation: about 3,000 concurrent requests read product:99 from Redis. The database is idle for this key.', flows: [{ from: 'pa', to: 'hot' }, { from: 'pb', to: 'hot' }, { from: 'pc', to: 'hot' }] },
    { caption: 'The TTL expires at one instant (or Redis restarts). Every in-flight request misses at the same time.', flows: [{ from: 'hot', to: 'pa', label: 'miss', color: 'red' }, { from: 'hot', to: 'pb', label: 'miss', color: 'red' }, { from: 'hot', to: 'pc', label: 'miss', color: 'red' }] },
    { caption: 'Stampede: all 3,000 misses run the same expensive query. Database CPU hits 100%, queries time out, clients retry and the load grows. Nobody ever refills the cache.', flows: [{ from: 'pa', to: 'db', label: '×1000', color: 'red' }, { from: 'pb', to: 'db', label: '×1000', color: 'red' }, { from: 'pc', to: 'db', label: '×1000', color: 'red' }], active: ['db'] },
    { caption: 'Layer 1, request coalescing: inside each pod singleflight lets one goroutine load the key while the other 999 wait for its result. The database sees 3 queries instead of 3,000.', flows: [{ from: 'pa', to: 'db', label: '1 load' }, { from: 'pb', to: 'db', label: '1 load' }, { from: 'pc', to: 'db', label: '1 load' }] },
    { caption: 'Layer 2, fleet-wide: the first misser takes a lock with SET NX PX. The others do not wait; they serve the stale value, which is still there because the hard TTL is longer than the soft one.', flows: [{ from: 'pa', to: 'lock', label: 'SET NX ok' }, { from: 'hot', to: 'pb', label: 'stale ok' }, { from: 'hot', to: 'pc', label: 'stale ok' }] },
    { caption: 'Pod A recomputes once, writes the new value with a jittered TTL (300 s ± 10%) so keys loaded together do not expire together, and releases the lock. Probabilistic early refresh (XFetch) is an alternative.', flows: [{ from: 'pa', to: 'db', label: 'recompute' }, { from: 'pa', to: 'hot', label: 'SET ttl±jitter' }] },
    { caption: 'Hot keys are the other face of the problem: a flash sale sends 500K reads/s to one key and saturates one shard. Replicate the key across shards and add a seconds-long in-process L1. Detect hot keys by sampling.', flows: [{ from: 'pb', to: 'reps', label: 'random copy' }, { from: 'pc', to: 'reps', label: 'random copy' }], active: ['hot'] },
  ],
});

// ===== Module 4: Databases & data scaling =======================================

registerDiagram({
  id: 'sd-replication-lag-failover',
  roadmap: 'system-design', module: 4, topic: 'Replication: Leader-Follower, Multi-Leader, Leaderless & Replication Lag',
  kind: 'graph',
  title: 'Leader-follower: semi-sync writes, a lagging read, then failover',
  desc: 'A single leader with one synchronous and one asynchronous follower. See why a user can lose their own write on refresh, how to fix it, and why failover should promote the synchronous follower and fence the old leader.',
  nodes: [
    { id: 'app', label: 'App', sub: 'read/write router', icon: '⚙️', x: 0, y: 2, color: 'blue', info: 'Sends writes to the leader and most reads to followers. It must know who the leader is after a failover, usually through a virtual IP, DNS or a proxy such as PgBouncer or HAProxy fed by the failover manager.' },
    { id: 'mgr', label: 'Failover manager', sub: 'Patroni + etcd', x: 2, y: 0, color: 'purple', info: 'Holds the leader lease in a consensus store (etcd). If the leader stops renewing its lease, the manager promotes the most up-to-date eligible follower. Consensus prevents two nodes from both believing they lead.' },
    { id: 'leader', label: 'Leader', sub: 'all writes, WAL', x: 2, y: 2, shape: 'db', color: 'green', exit: 5, info: 'The only node that accepts writes. It streams its write-ahead log (WAL) to followers. Write throughput is bounded by this one machine.' },
    { id: 'fa', label: 'Follower A', sub: 'synchronous', x: 4, y: 1, shape: 'db', color: 'teal', info: 'The leader waits for this follower to confirm each commit (semi-synchronous replication). It therefore holds every acknowledged write and is the safe promotion target. It costs one network round trip per commit.' },
    { id: 'fb', label: 'Follower B', sub: 'async, ~2 s behind', x: 4, y: 3, shape: 'db', color: 'yellow', info: 'Receives the WAL asynchronously, so it adds no write latency but may be seconds behind under load. Fine for analytics and most reads, dangerous for read-your-writes and as a promotion target.' },
  ],
  edges: [
    { from: 'app', to: 'leader', label: 'writes' },
    { from: 'leader', to: 'fa', label: 'WAL (sync)' },
    { from: 'leader', to: 'fb', label: 'WAL (async)' },
    { from: 'app', to: 'fb', curve: 40, dashed: true },
    { from: 'app', to: 'fa', curve: -40, dashed: true },
    { from: 'mgr', to: 'leader', dashed: true, label: 'lease' },
    { from: 'mgr', to: 'fa', dashed: true },
  ],
  steps: [
    { caption: 'A user changes their display name. The write goes to the leader, which appends it to its WAL.', flows: [{ from: 'app', to: 'leader', label: 'UPDATE name' }] },
    { caption: 'Semi-sync: the leader waits for Follower A to confirm before acknowledging the commit, so an acknowledged write exists on two machines. Follower B gets the change later, asynchronously.', flows: [{ from: 'leader', to: 'fa', label: 'WAL + ack' }, { from: 'leader', to: 'fb', label: 'WAL (later)', color: 'yellow' }] },
    { caption: 'The user refreshes the page. The read goes to Follower B, which is 2 s behind, and the old name comes back. The change seems to have vanished: read-your-writes is violated.', flows: [{ from: 'app', to: 'fb', label: 'SELECT name' }, { from: 'fb', to: 'app', label: 'old name', color: 'red' }] },
    { caption: 'Fixes: read your own data from the leader for a few seconds after writing, or remember the write LSN and read only from a replica that has replayed it. Pin each user to one replica so time never goes backwards between reads (monotonic reads).', flows: [{ from: 'app', to: 'leader', label: 'read own data' }], active: ['fa'] },
    { caption: 'The leader crashes. Writes fail and its lease in etcd stops being renewed. Async writes not yet shipped to Follower B exist only on the dead leader.', active: ['mgr', 'fa', 'fb'] },
    { caption: 'After the lease expires (about 10-30 s) the manager promotes Follower A. It was synchronous, so no acknowledged write is lost. Promoting B would have silently dropped up to 2 s of commits.', flows: [{ from: 'mgr', to: 'fa', label: 'promote' }] },
    { caption: 'The app writes to the new leader and B re-points to it. If the old leader comes back it must be fenced (lease revoked, STONITH) or two leaders accept writes: split brain.', flows: [{ from: 'app', to: 'fa', label: 'writes' }], active: ['fb'] },
  ],
});

registerDiagram({
  id: 'sd-resharding',
  roadmap: 'system-design', module: 4, topic: 'Partitioning / Sharding Strategies & Resharding',
  kind: 'graph',
  title: 'Live resharding: move logical partitions, flip the routing map',
  desc: 'Hash keys into many fixed logical partitions (1,024) and map those onto a few physical nodes. Adding capacity then means moving whole partitions and changing a map, never rehashing every key. Follow a zero-downtime split.',
  nodes: [
    { id: 'app', label: 'App', sub: 'user_id = 42', icon: '⚙️', x: 0, y: 2, color: 'blue', info: 'Every query carries the shard key. Queries that do not (for example "find user by email") need a global secondary index or a scatter-gather across all shards.' },
    { id: 'router', label: 'Shard router', sub: 'hash(key) % 1024', x: 2, y: 2, color: 'purple', info: 'Vitess vtgate, a client library or a proxy. It hashes the key to a logical partition (a fixed 1,024), then looks the partition up in the routing map to find the physical node.' },
    { id: 'map', label: 'Routing map', sub: 'partition → node', x: 2, y: 0, color: 'teal', info: 'A small, versioned table of partition ranges to nodes, cached by every router and watched for changes. It is the only thing that changes when data moves.' },
    { id: 'na', label: 'Node A', sub: 'partitions 0-511', x: 5, y: 1, shape: 'db', color: 'green', info: 'Each physical node owns a set of logical partitions. Moving a partition is a bounded copy of one slice of data.' },
    { id: 'nb', label: 'Node B', sub: 'partitions 512-1023', x: 5, y: 3, shape: 'db', color: 'orange', info: 'Becomes hot: 80% disk and high write latency. Partitions 768-1023 move to the new Node C.' },
    { id: 'nc', label: 'Node C', sub: 'new: 768-1023', x: 5, y: 5, shape: 'db', color: 'green', enter: 2, info: 'The new node. It receives a snapshot of the moving partitions, then streams changes until it is caught up, and only then is routed traffic.' },
  ],
  edges: [
    { from: 'app', to: 'router' },
    { from: 'router', to: 'map', label: 'lookup (cached)' },
    { from: 'router', to: 'na' }, { from: 'router', to: 'nb' }, { from: 'router', to: 'nc' },
    { from: 'nb', to: 'nc', label: 'snapshot + CDC', dashed: true },
  ],
  steps: [
    { caption: 'A query for user 42 arrives. hash(42) % 1024 = 817, and the routing map says partition 817 lives on Node B. The shard key decides which single shard answers.', flows: [{ from: 'app', to: 'router', label: 'user 42' }, { from: 'router', to: 'map', label: 'p817?' }, { from: 'router', to: 'nb', label: 'p817' }] },
    { caption: 'Node B is running hot. Add Node C. Because nodes hold logical partitions, nothing is rehashed: with hash mod N on physical nodes, going from 2 to 3 nodes would move about two thirds of all keys.', active: ['nb', 'nc'] },
    { caption: 'Copy a consistent snapshot of partitions 768-1023 from B to C. Writes continue on B the whole time.', flows: [{ from: 'nb', to: 'nc', label: 'bulk copy' }] },
    { caption: 'Stream the changes made since the snapshot (binlog or WAL, i.e. CDC) until C is only milliseconds behind. Reads and writes are still served by B.', flows: [{ from: 'router', to: 'nb', label: 'writes' }, { from: 'nb', to: 'nc', label: 'CDC tail' }] },
    { caption: 'Cut-over: pause writes to the moving partitions for a moment, let C apply the last changes, then update the routing map so 768-1023 point to C. Routers pick up the new map version.', flows: [{ from: 'router', to: 'map', label: '768-1023 → C', color: 'orange' }], active: ['nc'] },
    { caption: 'Traffic for partition 817 now goes to C. After verifying row counts and checksums, delete the moved data from B. Vitess, Citus and CockroachDB automate this workflow.', flows: [{ from: 'app', to: 'router', label: 'user 42' }, { from: 'router', to: 'nc', label: 'p817' }] },
  ],
});

// ===== Module 5: Distributed systems ===========================================

registerDiagram({
  id: 'sd-cap-partition',
  roadmap: 'system-design', module: 5, topic: 'CAP Theorem & PACELC',
  kind: 'graph',
  title: 'A network partition forces the choice: refuse (CP) or diverge (AP)',
  desc: 'Two replicas of the same data, one client on each side. Everything is fine until the link between them breaks. Then each operation must either fail or risk returning or accepting data the other side does not have.',
  groups: [
    { id: 'side1', label: 'Side 1 (majority)', x: 0, y: 0.5, w: 3, h: 2, color: 'blue' },
    { id: 'side2', label: 'Side 2 (minority)', x: 4, y: 0.5, w: 3, h: 2, color: 'orange' },
  ],
  nodes: [
    { id: 'c1', label: 'Client 1', icon: '💻', x: 0, y: 1, color: 'gray', info: 'Talks to the replica on its side of the network.' },
    { id: 'a', label: 'Replica A', sub: 'x = 1', x: 2, y: 1, shape: 'db', color: 'blue', info: 'Can still reach a majority of the cluster (imagine a third node on this side), so in a CP system it keeps serving.' },
    { id: 'b', label: 'Replica B', sub: 'x = 1 → ?', x: 4, y: 1, shape: 'db', color: 'orange', info: 'Isolated with no majority. In a CP system (etcd, Spanner, ZooKeeper) it must refuse; in an AP system (Cassandra, Dynamo) it keeps answering and reconciles later.' },
    { id: 'c2', label: 'Client 2', icon: '💻', x: 6, y: 1, color: 'gray', info: 'From this client\'s point of view a partition looks exactly like a slow or failed server. It cannot tell the difference.' },
    { id: 'cut', label: 'Partition', sub: 'link A-B down', icon: '✂️', x: 3, y: 2, color: 'red', enter: 2, info: 'Real networks partition: a switch fails, a cable is cut, a GC pause makes a node look dead. Since partitions cannot be ruled out, the real choice is C or A while one lasts. "CA" only describes a single node.' },
  ],
  edges: [
    { from: 'c1', to: 'a', both: true },
    { from: 'a', to: 'b', both: true, label: 'replication' },
    { from: 'c2', to: 'b', both: true },
  ],
  steps: [
    { caption: 'Normal operation: Client 1 writes x = 1 and A replicates to B. PACELC says that even now there is a trade-off: wait for B (consistent, slower) or acknowledge first (fast, briefly stale on B).', flows: [{ from: 'c1', to: 'a', label: 'x = 1' }, { from: 'a', to: 'b', label: 'replicate' }] },
    { caption: 'The link between the replicas breaks. Both nodes are up and both clients can reach their own replica, but A and B can no longer talk.', active: ['cut', 'a', 'b'] },
    { caption: 'CP choice: B cannot reach a majority, so it rejects Client 2\'s write (and linearizable reads). The data stays consistent but the minority side is unavailable. Right for payments, inventory and unique usernames.', flows: [{ from: 'c2', to: 'b', label: 'x = 2' }, { from: 'b', to: 'c2', label: 'error', color: 'red' }] },
    { caption: 'AP choice: B accepts x = 2 while A still serves x = 1. Both sides stay available, but they now disagree and clients read different values. Right for carts, feeds, likes and presence.', flows: [{ from: 'c2', to: 'b', label: 'x = 2 ok' }, { from: 'a', to: 'c1', label: 'x = 1', color: 'yellow' }] },
    { caption: 'When the partition heals, the AP replicas exchange updates and resolve the conflict: last-writer-wins (simple, silently drops a write), vector clocks with an app merge, or CRDTs that merge automatically.', flows: [{ from: 'a', to: 'b', label: 'x = 1' }, { from: 'b', to: 'a', label: 'x = 2' }] },
    { caption: 'Choose per operation, not per company: the same product can use AP for the cart and CP for checkout. Note that CAP consistency means linearizability, not the C of ACID.', active: ['side1', 'side2', 'a', 'b'] },
  ],
});

registerDiagram({
  id: 'sd-raft',
  roadmap: 'system-design', module: 5, topic: 'Quorums, Consensus (Raft) & Leader Election',
  kind: 'graph',
  title: 'Raft: commit on a majority, re-elect when the leader dies',
  desc: 'A five-node Raft cluster tolerates two failures. Follow one write from client to committed, then kill the leader and watch a follower with a randomised timeout win the election for the next term.',
  nodes: [
    { id: 'client', label: 'Client', icon: '💻', x: 0, y: 2, color: 'gray', info: 'Sends commands to the leader. A follower that receives a request redirects the client to the current leader.' },
    { id: 's1', label: 'S1', sub: 'leader · term 1', x: 2, y: 2, color: 'blue', exit: 5, info: 'The only node that accepts writes in term 1. It sends AppendEntries (with entries, or empty as heartbeats) to every follower about every 50 ms.' },
    { id: 's2', label: 'S2', sub: 'follower', x: 4, y: 0, color: 'teal', info: 'Appends entries in the order the leader sends them and acknowledges. It rejects entries whose predecessor does not match its own log.' },
    { id: 's3', label: 'S3', sub: 'follower → leader', x: 6, y: 1, color: 'teal', info: 'Its randomised election timeout (150-300 ms) fires first after S1 dies, so it becomes the candidate for term 2. Randomisation makes split votes rare.' },
    { id: 's4', label: 'S4', sub: 'follower', x: 6, y: 3, color: 'teal', info: 'Grants its vote to the first candidate in a term whose log is at least as up to date as its own. One vote per term.' },
    { id: 's5', label: 'S5', sub: 'follower (slow)', x: 4, y: 4, color: 'teal', info: 'A slow or briefly partitioned follower. The cluster does not wait for it: a majority is enough. It catches up when its connection recovers.' },
  ],
  edges: [
    { from: 'client', to: 's1' },
    { from: 's1', to: 's2', label: 'AppendEntries' },
    { from: 's1', to: 's3' },
    { from: 's1', to: 's4' },
    { from: 's1', to: 's5' },
  ],
  steps: [
    { caption: 'Steady state: S1 is leader for term 1 and sends heartbeats (empty AppendEntries) to every follower. As long as heartbeats arrive, no follower starts an election.', flows: [{ from: 's1', to: 's2', label: '♥' }, { from: 's1', to: 's3', label: '♥' }, { from: 's1', to: 's4', label: '♥' }, { from: 's1', to: 's5', label: '♥' }] },
    { caption: 'A client sends SET x=5. The leader appends it to its log at index 7. The entry is not committed yet, and S1 does not reply to the client.', flows: [{ from: 'client', to: 's1', label: 'SET x=5' }] },
    { caption: 'S1 replicates entry 7 to all followers in parallel. Each follower checks that its log matches at index 6 and appends the entry.', flows: [{ from: 's1', to: 's2', label: 'idx 7' }, { from: 's1', to: 's3', label: 'idx 7' }, { from: 's1', to: 's4', label: 'idx 7' }, { from: 's1', to: 's5', label: 'idx 7' }] },
    { caption: 'S2 and S3 acknowledge. With S1 itself that is 3 of 5, a majority, so entry 7 is committed and applied, and the client gets OK. S4 and S5 can be slow without blocking anything.', flows: [{ from: 's2', to: 's1', label: 'ack' }, { from: 's3', to: 's1', label: 'ack' }, { from: 's1', to: 'client', label: 'OK', color: 'green' }] },
    { caption: 'S1 crashes. Heartbeats stop. Every committed entry is on at least 3 nodes, so any majority the next leader gathers includes at least one node that has it.', active: ['s2', 's3', 's4', 's5'] },
    { caption: 'S3\'s randomised timeout fires first. It increments the term to 2, votes for itself and sends RequestVote, including the index and term of its last log entry.', flows: [{ from: 's3', to: 's2', label: 'vote? t2' }, { from: 's3', to: 's4', label: 'vote? t2' }, { from: 's3', to: 's5', label: 'vote? t2' }] },
    { caption: 'S2 and S4 grant their votes because S3\'s log is at least as up to date as theirs. With its own vote that makes 3 of 5. A node missing a committed entry could never win, which is how Raft keeps committed entries safe.', flows: [{ from: 's2', to: 's3', label: 'yes', color: 'green' }, { from: 's4', to: 's3', label: 'yes', color: 'green' }] },
    { caption: 'S3 is leader for term 2 and starts sending heartbeats; clients are redirected to it. If S1 returns it sees the higher term and steps down. Five nodes tolerate two failures; four would still tolerate only one.', flows: [{ from: 'client', to: 's3', label: 'requests' }, { from: 's3', to: 's4', label: '♥' }, { from: 's3', to: 's2', label: '♥' }] },
  ],
});

registerDiagram({
  id: 'sd-vector-clocks',
  roadmap: 'system-design', module: 5, topic: 'Clocks: Physical, Lamport, Vector and Hybrid',
  kind: 'sequence',
  title: 'Vector clocks detect concurrent writes that Lamport clocks hide',
  desc: 'Three replicas, each keeping a vector [A, B, C]. Watch the merge rule on every receive, then compare two writes to the same key: neither vector dominates, so the writes are concurrent and must be merged instead of overwritten.',
  actors: [
    { id: 'a', label: 'Replica A', sub: 'vector [A,B,C]', color: 'blue', info: 'Increments its own entry on every event (local write, send, receive). On receive it first takes the element-wise max with the incoming vector.' },
    { id: 'b', label: 'Replica B', sub: 'vector [A,B,C]', color: 'green', info: 'Same rules. A vector clock has one counter per node, so it grows with the number of writers; Dynamo-style stores prune or use per-key version vectors.' },
    { id: 'c', label: 'Replica C', sub: 'vector [A,B,C]', color: 'orange', info: 'Accepts a write locally while it has not heard from A. That write is concurrent with A\'s later write, and only the vectors can prove it.' },
  ],
  steps: [
    { section: 'Events and messages' },
    { from: 'a', to: 'b', label: 'm1 @ [1,0,0]', caption: 'A\'s first event is sending m1. It increments its own entry and attaches [1,0,0].' },
    { from: 'b', to: 'b', label: 'recv → [1,1,0]', caption: 'B merges: element-wise max of its [0,0,0] and [1,0,0], then increments its own entry, giving [1,1,0]. B now causally knows about A\'s event.' },
    { from: 'c', to: 'c', label: 'write x → [0,0,1]', caption: 'Meanwhile C accepts a local write to key x. It has heard from nobody, so its vector is [0,0,1].' },
    { from: 'b', to: 'c', label: 'm2 @ [1,2,0]', caption: 'B sends m2, incrementing to [1,2,0].' },
    { from: 'c', to: 'c', label: 'recv → [1,2,2]', caption: 'C merges max([0,0,1], [1,2,0]) = [1,2,1] and increments its own entry: [1,2,2]. Through B, C now knows about m1 too: causality is transitive.' },
    { from: 'a', to: 'a', label: 'write x → [2,0,0]', caption: 'A also writes key x. It has not received anything from C, so its vector is [2,0,0].' },
    { section: 'Comparing the two writes to x' },
    { from: 'a', to: 'c', label: 'replicate x @ [2,0,0]', caption: 'A replicates its version of x to C. C must decide whether A\'s write replaces its own write of x, tagged [0,0,1].' },
    { from: 'c', to: 'c', label: 'neither dominates', caption: '[2,0,0] vs [0,0,1]: each is larger in some entry, so neither happened before the other. C keeps both as siblings for the app or a CRDT to merge. Lamport stamps (2 vs 1) would let last-writer-wins silently drop C\'s write.' },
  ],
});

registerDiagram({
  id: 'sd-idempotency-key',
  roadmap: 'system-design', module: 5, topic: 'Idempotency & Delivery Semantics',
  kind: 'sequence',
  title: 'Idempotency keys: a lost response, a retry, and no double charge',
  desc: 'The network can lose the response after the work is done, so the client cannot tell "failed" from "succeeded but I never heard". A client-generated key per logical operation lets the server recognise the retry and replay the original answer.',
  actors: [
    { id: 'c', label: 'Client', sub: 'mobile app', icon: '📱', color: 'gray', info: 'Generates one UUID per logical operation (per checkout click, not per HTTP attempt) and reuses it for every retry of that operation.' },
    { id: 'api', label: 'Payments API', sub: 'stateless', color: 'blue', info: 'Checks the key before doing any work and stores the result after. Keys are scoped per merchant or user and kept about 24 hours.' },
    { id: 'store', label: 'Idempotency store', sub: 'Postgres, UNIQUE key', color: 'teal', info: 'Row: key, request hash, status (in_progress, done), response code and body. A UNIQUE constraint on the key makes the insert itself the lock.' },
    { id: 'psp', label: 'Card processor', sub: 'external PSP', color: 'purple', info: 'The side effect we must not repeat. Pass the same idempotency key on to the PSP too, so a retry at that layer is also safe.' },
  ],
  steps: [
    { section: 'First attempt' },
    { from: 'c', to: 'api', label: 'POST /pay, Key: K1', caption: 'The client sends a payment of $50 with header Idempotency-Key: K1.' },
    { from: 'api', to: 'store', label: 'INSERT K1 in_progress', caption: 'The API inserts K1 with a hash of the request body and status in_progress. If the insert hits the UNIQUE constraint, this is a duplicate.' },
    { from: 'api', to: 'psp', label: 'charge $50 (key K1)', caption: 'The insert succeeded, so this is the first attempt: charge the card.' },
    { from: 'psp', to: 'api', label: 'approved', reply: true, caption: 'The processor approves the charge.' },
    { from: 'api', to: 'store', label: 'K1 → done, 201 + body', caption: 'The API stores the final status code and response body under K1.' },
    { from: 'api', to: 'c', label: '201 (lost in transit)', reply: true, caption: 'The response is lost: the phone switched from Wi-Fi to cellular. The client times out without knowing whether it was charged.' },
    { section: 'Retry with the same key' },
    { from: 'c', to: 'api', label: 'retry, Key: K1', caption: 'The client retries the same operation with the same key K1, with backoff and jitter.' },
    { from: 'api', to: 'store', label: 'lookup K1', caption: 'The insert conflicts, so the API reads the existing row.' },
    { from: 'store', to: 'api', label: 'done: 201 + body', reply: true, caption: 'The row says done and holds the original response.' },
    { from: 'api', to: 'c', label: '201 (replayed)', reply: true, caption: 'The API returns the stored response without calling the processor again. The customer is charged exactly once: at-least-once delivery plus deduplication gives effectively-once processing.' },
    { section: 'Edge cases interviewers probe' },
    { from: 'c', to: 'api', label: 'K2 dup while running', caption: 'A duplicate arrives while the first request with K2 is still in progress (a double tap).' },
    { from: 'api', to: 'c', label: '409 in progress', reply: true, caption: 'Return 409 Conflict and let the client retry later. Never run the two concurrently.' },
    { from: 'c', to: 'api', label: 'K1 with $70 body', caption: 'A buggy client reuses K1 with a different amount.' },
    { from: 'api', to: 'c', label: '422 key reused', reply: true, caption: 'The stored request hash does not match, so reject it. Silently replaying the $50 response would hide a client bug.' },
  ],
});

registerDiagram({
  id: 'sd-2pc',
  roadmap: 'system-design', module: 5, topic: 'Distributed Transactions: 2PC vs Saga',
  kind: 'sequence',
  title: 'Two-phase commit, and why a coordinator crash blocks everyone',
  desc: 'A coordinator makes three databases commit atomically: all prepare, then all commit. It works, but once participants have voted yes they cannot decide on their own. If the coordinator dies then, their locks stay held.',
  actors: [
    { id: 'co', label: 'Coordinator', sub: 'transaction manager', icon: '🧭', color: 'purple', info: 'Collects votes and makes the decision. Its decision log is the single source of truth for the outcome, which is why it is the weak point.' },
    { id: 'ord', label: 'Orders DB', sub: 'participant', color: 'blue', info: 'On PREPARE it writes the changes and a prepare record durably, takes the locks and promises it can commit whatever happens.' },
    { id: 'inv', label: 'Inventory DB', sub: 'participant', color: 'green', info: 'Holds row locks on the stock it will decrement from PREPARE until it hears COMMIT or ABORT.' },
    { id: 'pay', label: 'Payments DB', sub: 'participant', color: 'orange', info: 'If it votes NO (or times out before voting), the coordinator aborts everyone.' },
  ],
  steps: [
    { section: 'Phase 1: prepare (vote)' },
    { from: 'co', to: 'ord', label: 'PREPARE tx42', caption: 'The coordinator asks every participant to prepare transaction 42.' },
    { from: 'co', to: 'inv', label: 'PREPARE tx42', caption: 'Each participant writes its changes and a prepare record to disk and takes its locks.' },
    { from: 'co', to: 'pay', label: 'PREPARE tx42', caption: 'A participant that votes yes gives up the right to abort on its own.' },
    { from: 'ord', to: 'co', label: 'YES', reply: true, caption: 'Orders votes yes. Its locks are now held until it hears the decision.' },
    { from: 'inv', to: 'co', label: 'YES', reply: true, caption: 'Inventory votes yes.' },
    { from: 'pay', to: 'co', label: 'YES', reply: true, caption: 'Payments votes yes. If anyone had voted no, the coordinator would send ABORT to all.' },
    { section: 'Phase 2: commit' },
    { from: 'co', to: 'co', label: 'log COMMIT tx42', caption: 'The decision becomes final the moment the coordinator durably logs COMMIT. After a crash it re-reads the log and re-sends the decision.' },
    { from: 'co', to: 'ord', label: 'COMMIT', caption: 'Commit messages go out; each participant makes its changes visible and releases its locks.' },
    { from: 'co', to: 'inv', label: 'COMMIT', caption: 'Inventory commits.' },
    { from: 'co', to: 'pay', label: 'COMMIT', caption: 'Payments commits. Atomic and isolated, at the cost of two round trips with locks held across the network.' },
    { section: 'Failure: coordinator dies after votes' },
    { from: 'co', to: 'co', label: 'crash, no decision', caption: 'For tx43, all participants voted yes, then the coordinator crashed before logging or sending a decision.' },
    { from: 'inv', to: 'inv', label: 'in doubt, locked', caption: 'Inventory cannot commit (maybe someone else voted no) and cannot abort (maybe the coordinator logged commit). It holds its locks, blocking other orders for that stock.' },
    { from: 'inv', to: 'co', label: 'decision for tx43?', caption: 'It waits until the coordinator recovers. This blocking is why 2PC stays inside one system or uses a replicated coordinator (Spanner runs it over Paxos groups). Across microservices, use a saga.' },
  ],
});

registerDiagram({
  id: 'sd-saga-checkout',
  roadmap: 'system-design', module: 5, problem: 'Saga for e-commerce checkout',
  kind: 'sequence',
  title: 'Orchestrated checkout saga: compensate before the pivot, retry after',
  desc: 'Each step is a local transaction in one service. Before the card is authorised, a failure is undone with compensations in reverse order. Authorising the card is the pivot: after it succeeds the saga only moves forward, retrying until done.',
  actors: [
    { id: 'orch', label: 'Orchestrator', sub: 'Temporal workflow', icon: '🧭', color: 'purple', info: 'Durably records each step\'s result, so after a crash it resumes where it left off. Every command it sends must be idempotent because it may be sent twice.' },
    { id: 'ord', label: 'Order svc', sub: 'semantic lock', color: 'blue', info: 'The PENDING status is a semantic lock: other flows can see the order is not final yet. Sagas have no isolation, so intermediate states are visible.' },
    { id: 'inv', label: 'Inventory svc', sub: 'reserve / release', color: 'green', info: 'Reserving stock (not decrementing it) makes the compensation trivial and prevents overselling while the saga runs.' },
    { id: 'pay', label: 'Payment svc', sub: 'authorise = pivot', color: 'orange', info: 'Authorise first and capture at shipment. An authorisation can be voided cheaply, while a captured charge needs a refund.' },
    { id: 'ship', label: 'Shipping svc', sub: 'retriable', color: 'teal', info: 'After the pivot this step must eventually succeed. Make it retriable with backoff and send persistent failures to a DLQ for ops, not to compensation.' },
  ],
  steps: [
    { section: 'Run 1: card declined before the pivot' },
    { from: 'orch', to: 'ord', label: 'create order PENDING', caption: 'Step 1: create the order in PENDING state, a local transaction in the Order service. Its event goes out via the transactional outbox.' },
    { from: 'orch', to: 'inv', label: 'reserve 2 items', caption: 'Step 2: reserve the items. The compensation, release, is registered in case a later step fails.' },
    { from: 'inv', to: 'orch', label: 'reserved', reply: true, caption: 'The stock is held for this order.' },
    { from: 'orch', to: 'pay', label: 'authorise $80', caption: 'Step 3, the pivot: authorise the card.' },
    { from: 'pay', to: 'orch', label: 'declined', reply: true, caption: 'The card is declined. The saga has not passed the pivot, so it rolls back by compensating completed steps in reverse order.' },
    { from: 'orch', to: 'inv', label: 'release items', caption: 'Compensate step 2: release the reservation. Compensations must be idempotent and must not fail permanently.' },
    { from: 'orch', to: 'ord', label: 'mark CANCELLED', caption: 'Compensate step 1: cancel the order. Nothing is deleted; the history shows what happened, which is useful for audits.' },
    { section: 'Run 2: pivot succeeds, then forward only' },
    { from: 'orch', to: 'pay', label: 'authorise $80', caption: 'On a later checkout (order created and items reserved as before) the authorisation is approved. From here the saga only moves forward.' },
    { from: 'pay', to: 'orch', label: 'authorised', reply: true, caption: 'The pivot succeeded.' },
    { from: 'orch', to: 'ship', label: 'create shipment', caption: 'Step 4: create the shipment.' },
    { from: 'ship', to: 'orch', label: '503 carrier down', reply: true, caption: 'Shipping fails transiently. Undoing a successful payment would be worse than waiting, so the orchestrator retries.' },
    { from: 'orch', to: 'ship', label: 'retry (same key)', caption: 'Retry with exponential backoff and the same idempotency key, so a retry that races a slow success creates one shipment, not two.' },
    { from: 'ship', to: 'orch', label: 'shipment created', reply: true, caption: 'The shipment is created.' },
    { from: 'orch', to: 'ord', label: 'mark CONFIRMED', caption: 'Step 5: the order is CONFIRMED and the semantic lock is released. Interviewers probe exactly this: where the pivot sits, idempotent steps, and how to live without isolation.' },
  ],
});

// ===== Module 6: Asynchronous processing & messaging ============================

registerDiagram({
  id: 'sd-queue-pubsub-log',
  roadmap: 'system-design', module: 6, topic: 'Message Queues vs Pub/Sub vs Log-Based Streams',
  kind: 'graph',
  title: 'Queue, pub/sub and log: who gets each message, and what remains',
  desc: 'Three brokers, three consumption models. A queue hands each message to one worker and deletes it. Pub/sub copies it to every subscription. A log keeps it, and every consumer group reads at its own offset, so you can replay.',
  groups: [
    { id: 'gq', label: 'Work queue (SQS, RabbitMQ)', x: 0, y: 0, w: 5, h: 2, color: 'blue' },
    { id: 'gps', label: 'Pub/sub (SNS, Google Pub/Sub)', x: 0, y: 2, w: 5, h: 2, color: 'purple' },
    { id: 'glog', label: 'Log-based stream (Kafka, Kinesis)', x: 0, y: 4, w: 6, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'pq', label: 'Producer', sub: 'resize jobs', x: 0, y: 0.5, color: 'gray', info: 'Enqueues work items. It does not know or care which worker will process each one.' },
    { id: 'queue', label: 'Queue', sub: 'ack, retry, DLQ', x: 2, y: 0.5, color: 'blue', info: 'A message is hidden while a worker processes it (visibility timeout) and deleted on ack. If the worker dies, it reappears for another worker. Rich per-message features: delay, priority, dead-letter queue.' },
    { id: 'w1', label: 'Worker 1', x: 4, y: 0, color: 'blue', info: 'Competing consumers: add workers to drain the queue faster. Ordering across workers is best effort.' },
    { id: 'w2', label: 'Worker 2', x: 4, y: 1, color: 'blue', info: 'Gets different messages from Worker 1, never the same one at the same time.' },
    { id: 'pub', label: 'Publisher', sub: 'OrderPlaced', x: 0, y: 2.5, color: 'gray', info: 'Publishes an event once, without knowing who is interested.' },
    { id: 'topic', label: 'Topic', sub: 'fan-out', x: 2, y: 2.5, color: 'purple', info: 'Copies each message into every subscription. A common pattern is SNS to several SQS queues, giving each consumer its own buffer and retries.' },
    { id: 'sa', label: 'Email svc', sub: 'own subscription', x: 4, y: 2, color: 'purple', info: 'Receives every event. Deleting it from this subscription does not affect other subscribers.' },
    { id: 'sb', label: 'Analytics svc', sub: 'own subscription', x: 4, y: 3, color: 'purple', info: 'Also receives every event. A subscriber that did not exist when an event was published never sees it.' },
    { id: 'pl', label: 'Producer', sub: 'key = order_id', x: 0, y: 5, color: 'gray', info: 'Appends to the log. The key picks the partition, so events with the same key stay in order.' },
    { id: 'log', label: 'Partition log', sub: 'offsets 0 … 42, kept 7 days', x: 2, y: 5, w: 2, color: 'green', info: 'An append-only, retained sequence. Reading does not delete anything; consumers only move their own offset. That makes replay, late joiners and multiple independent readers cheap.' },
    { id: 'gx', label: 'Group: billing', sub: 'offset 42', x: 5, y: 4, color: 'green', info: 'Caught up. Its committed offset says which events it has processed.' },
    { id: 'gy', label: 'Group: search', sub: 'offset 17 (lagging)', x: 5, y: 5, color: 'yellow', info: 'Slow, but it slows nobody else down. Consumer lag (head offset minus committed offset) is the key SLI of a stream consumer.' },
    { id: 'gz', label: 'Group: new ML job', sub: 'replay from 0', x: 5, y: 6, color: 'teal', enter: 6, info: 'Created months after the events were written. It backfills from history, which a queue or pub/sub system cannot offer.' },
  ],
  edges: [
    { from: 'pq', to: 'queue' }, { from: 'queue', to: 'w1' }, { from: 'queue', to: 'w2' },
    { from: 'pub', to: 'topic' }, { from: 'topic', to: 'sa' }, { from: 'topic', to: 'sb' },
    { from: 'pl', to: 'log' }, { from: 'log', to: 'gx' }, { from: 'log', to: 'gy' }, { from: 'log', to: 'gz' },
  ],
  steps: [
    { caption: 'Queue: the producer enqueues two image-resize jobs. Use a queue to distribute work and level load: the producer stays fast even when workers are slow or down.', flows: [{ from: 'pq', to: 'queue', label: 'm1, m2' }] },
    { caption: 'Competing consumers: m1 goes to Worker 1 and m2 to Worker 2, never both. Each message is deleted on ack; if a worker dies mid-job, the visibility timeout returns the message to the queue.', flows: [{ from: 'queue', to: 'w1', label: 'm1' }, { from: 'queue', to: 'w2', label: 'm2' }] },
    { caption: 'Pub/sub: one OrderPlaced event is copied to every subscription, so email and analytics both get it and neither knows about the other. Good for notifications and fan-out to many services.', flows: [{ from: 'pub', to: 'topic', label: 'OrderPlaced' }, { from: 'topic', to: 'sa', label: 'copy' }, { from: 'topic', to: 'sb', label: 'copy' }] },
    { caption: 'Log: the producer appends at offset 42. Nothing is removed when it is read; retention is by time or size (or compaction by key). Ordering is strict within a partition.', flows: [{ from: 'pl', to: 'log', label: 'append @42' }] },
    { caption: 'Each consumer group reads the whole log at its own pace: billing is at 42, search lags at 17. A slow group does not slow the others or the producer.', flows: [{ from: 'log', to: 'gx', label: 'read 42' }, { from: 'log', to: 'gy', label: 'read 17' }] },
    { caption: 'Replay: a new ML job starts a new group from offset 0 and backfills months of history, or a fixed consumer rewinds after a bug. This is why logs back event sourcing, CDC and analytics.', flows: [{ from: 'log', to: 'gz', label: 'from offset 0' }] },
  ],
});

registerDiagram({
  id: 'sd-kafka-groups',
  roadmap: 'system-design', module: 6, topic: 'Kafka Essentials: Partitions, Consumer Groups, Offsets, Ordering',
  kind: 'graph',
  title: 'Kafka: keys pick partitions, groups split partitions among consumers',
  desc: 'A topic with three partitions, one consumer group that scales from two to four members, and a second group reading the same data independently. Watch per-key ordering, a rebalance, committed offsets and the parallelism ceiling.',
  groups: [
    { id: 'topic', label: 'topic: orders', x: 2, y: 0.5, w: 1, h: 4, color: 'green' },
    { id: 'ga', label: 'group A: billing', x: 4, y: 0.5, w: 1, h: 4.5, color: 'blue' },
  ],
  nodes: [
    { id: 'prod', label: 'Producer', sub: 'key = order_id', x: 0, y: 2, color: 'gray', info: 'The default partitioner hashes the key (murmur2) modulo the partition count. With acks=all and idempotence (default since Kafka 3.0), retries do not create duplicates or reorder within a partition.' },
    { id: 'p0', label: 'P0', sub: 'offsets 0..918', x: 2, y: 1, shape: 'db', color: 'green', info: 'Each partition is an ordered, append-only log replicated to 3 brokers (one leader, followers in the ISR). Order is guaranteed only inside one partition.' },
    { id: 'p1', label: 'P1', sub: 'offsets 0..1204', x: 2, y: 2, shape: 'db', color: 'green', info: 'All events for order-42 land here, in the order they were produced.' },
    { id: 'p2', label: 'P2', sub: 'offsets 0..877', x: 2, y: 3, shape: 'db', color: 'green', info: 'Partition count is the unit of parallelism. Adding partitions later changes key-to-partition mapping, so over-provision moderately up front.' },
    { id: 'c1', label: 'Consumer C1', sub: 'P0 (+P1 at first)', x: 4, y: 1, color: 'blue', info: 'Owns P0, and P1 until C3 joins. Within a group each partition has exactly one owner at a time, which is what preserves per-key order.' },
    { id: 'c3', label: 'Consumer C3', sub: 'joins: takes P1', x: 4, y: 2, color: 'blue', enter: 4, info: 'Joining triggers a rebalance. With the cooperative-sticky assignor (or the KIP-848 protocol) only the moved partition pauses, not the whole group.' },
    { id: 'c2', label: 'Consumer C2', sub: 'P2', x: 4, y: 3, color: 'blue', info: 'Commits its offset for P2 after processing each batch.' },
    { id: 'c4', label: 'Consumer C4', sub: 'idle: no partition', x: 4, y: 4, color: 'gray', enter: 6, info: 'Four consumers, three partitions: one sits idle as a hot standby. Max useful parallelism in a group equals the partition count.' },
    { id: 'offs', label: 'Committed offsets', sub: '__consumer_offsets', x: 6, y: 2, color: 'teal', info: 'An internal compacted topic storing group, partition and offset. After a crash or rebalance the new owner resumes from the last committed offset.' },
    { id: 'gb', label: 'Group B consumer', sub: 'analytics', x: 0, y: 4, color: 'purple', info: 'A different group reads all three partitions with its own offsets. Fan-out costs no extra copies of the data, only extra reads.' },
  ],
  edges: [
    { from: 'prod', to: 'p0' }, { from: 'prod', to: 'p1' }, { from: 'prod', to: 'p2' },
    { from: 'p0', to: 'c1' }, { from: 'p1', to: 'c3' }, { from: 'p2', to: 'c2' },
  ],
  steps: [
    { caption: 'The producer sends events keyed by order_id. hash("order-42") % 3 = 1, so every event for order 42 goes to P1 and is consumed in the order it was produced.', flows: [{ from: 'prod', to: 'p1', label: 'order-42 #1, #2' }] },
    { caption: 'Other keys land on other partitions. There is no ordering between partitions: order-7 on P0 may be processed before or after order-42 on P1. Design so that only per-key order matters.', flows: [{ from: 'prod', to: 'p0', label: 'order-7' }, { from: 'prod', to: 'p2', label: 'order-9' }] },
    { caption: 'Group A has two consumers. C1 owns P0 and P1, C2 owns P2. Each partition has exactly one owner in the group, so two consumers never process the same key at the same time.', flows: [{ from: 'p0', to: 'c1' }, { from: 'p1', to: 'c1' }, { from: 'p2', to: 'c2' }] },
    { caption: 'C3 joins and the group rebalances: P1 moves from C1 to C3. Only P1 pauses briefly. Throughput grows because work is split by partition.', flows: [{ from: 'p1', to: 'c3', label: 'P1 reassigned' }] },
    { caption: 'After processing a batch each consumer commits its offset. Commit after processing gives at-least-once (a crash replays the uncommitted tail), so handlers must be idempotent. Commit before gives at-most-once.', flows: [{ from: 'c3', to: 'offs', label: 'commit P1 @ 1204' }], active: ['c1', 'c2'] },
    { caption: 'C4 joins but there is no partition left, so it sits idle. To scale beyond 3 consumers you need more partitions, and adding them later remaps keys and breaks per-key order during the change.', active: ['c4', 'topic'] },
    { caption: 'Group B (analytics) reads all three partitions independently with its own offsets. Many groups can read one topic without slowing each other: this is Kafka\'s fan-out.', flows: [{ from: 'p0', to: 'gb' }, { from: 'p1', to: 'gb' }, { from: 'p2', to: 'gb' }] },
  ],
});

registerDiagram({
  id: 'sd-outbox-cdc',
  roadmap: 'system-design', module: 6, topic: 'Transactional Outbox & Change Data Capture',
  kind: 'graph',
  title: 'Transactional outbox + CDC: one commit, guaranteed event',
  desc: 'Writing to the database and publishing to Kafka are two systems, so doing both is never atomic. Write the event into an outbox table in the same transaction, and let a CDC relay stream it from the database log to Kafka.',
  groups: [
    { id: 'pg', label: 'Postgres: 1 tx', x: 2, y: 0.5, w: 1, h: 2.5, color: 'green' },
  ],
  nodes: [
    { id: 'svc', label: 'Order service', sub: 'PlaceOrder()', x: 0, y: 2, color: 'blue', info: 'Business logic only: it writes rows in one local transaction and never calls the broker directly.' },
    { id: 'orders', label: 'orders table', sub: 'INSERT order 42', x: 2, y: 1, color: 'green', info: 'The business change.' },
    { id: 'outbox', label: 'outbox table', sub: 'INSERT OrderPlaced', x: 2, y: 2, color: 'green', info: 'Columns: event id (UUID), aggregate type and id, event type, payload, created_at. It is a deliberate, versioned public contract, unlike raw table changes.' },
    { id: 'cdc', label: 'Debezium', sub: 'tails the WAL', x: 4, y: 2, color: 'purple', info: 'Reads the write-ahead log through a logical replication slot, so it sees committed changes in commit order without polling. The outbox event router turns outbox rows into Kafka messages keyed by aggregate id.' },
    { id: 'kafka', label: 'Kafka', sub: 'order-events', x: 6, y: 2, shape: 'db', color: 'orange', info: 'Keyed by order id, so all events for one order stay in order on one partition.' },
    { id: 'email', label: 'Email service', sub: 'inbox: dedupe by id', x: 6, y: 0, color: 'teal', info: 'Records processed event ids in an inbox table in the same transaction as its own effect, so a redelivered event is skipped.' },
    { id: 'search', label: 'Search indexer', sub: 'idempotent upsert', x: 6, y: 4, color: 'teal', info: 'Upserting a document by id is naturally idempotent, so duplicates are harmless.' },
  ],
  edges: [
    { from: 'svc', to: 'orders' }, { from: 'svc', to: 'outbox' },
    { from: 'outbox', to: 'cdc', label: 'WAL' },
    { from: 'cdc', to: 'kafka', label: 'publish' },
    { from: 'kafka', to: 'email' }, { from: 'kafka', to: 'search' },
    { from: 'svc', to: 'kafka', dashed: true, curve: 140, label: 'dual write (broken)' },
  ],
  steps: [
    { caption: 'The dual-write trap: commit the order, then publish to Kafka. If the broker is down or the pod dies in between, the event is lost. Publish first and the commit may roll back: a phantom event.', flows: [{ from: 'svc', to: 'orders', label: 'COMMIT' }, { from: 'svc', to: 'kafka', label: 'publish ✗', color: 'red' }] },
    { caption: 'Outbox: insert the order row and the OrderPlaced event row in the same local transaction. Both commit or neither does, with no distributed transaction.', flows: [{ from: 'svc', to: 'orders', label: 'INSERT' }, { from: 'svc', to: 'outbox', label: 'INSERT event' }], active: ['pg'] },
    { caption: 'Debezium reads the committed outbox insert from the WAL: low latency, no polling load, commit order preserved. A polling relay (SELECT ... FOR UPDATE SKIP LOCKED) also works, at the cost of extra queries and latency.', flows: [{ from: 'outbox', to: 'cdc', label: 'committed row' }] },
    { caption: 'The relay publishes to Kafka keyed by order id. If it crashes after publishing but before recording its position, it publishes again: delivery is at-least-once.', flows: [{ from: 'cdc', to: 'kafka', label: 'OrderPlaced' }] },
    { caption: 'Consumers must tolerate duplicates: the email service keeps an inbox of processed event ids, and the search indexer upserts by id. At-least-once plus idempotent consumers gives effectively-once.', flows: [{ from: 'kafka', to: 'email', label: 'event e-91' }, { from: 'kafka', to: 'search', label: 'event e-91' }] },
    { caption: 'Raw CDC of the orders table would also work, but it exposes your internal schema to other teams. Use the outbox for integration events and raw CDC for derived data you own (caches, search, warehouse).', active: ['orders', 'outbox', 'cdc'] },
  ],
});

