registerDiagram({
  id: 'sd-gateway-discovery',
  roadmap: 'system-design', module: 7, topic: 'API Gateway & Service Discovery',
  kind: 'graph',
  title: 'API gateway at the edge, service registry for moving instances',
  desc: 'External clients see one stable entry point that authenticates, limits and routes. Behind it, instances come and go with autoscaling and failures, so the gateway asks a registry which healthy instances exist right now.',
  groups: [
    { id: 'orders', label: 'orders service', x: 4, y: 2, w: 1, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'client', label: 'Mobile / web', icon: '📱', x: 0, y: 2, color: 'gray', info: 'Knows one hostname, api.example.com. It never sees internal service names or instance IPs.' },
    { id: 'gw', label: 'API gateway', sub: 'auth, limits, route', x: 2, y: 2, color: 'blue', info: 'TLS termination, JWT validation, rate limits and quotas, routing by path, request aggregation, access logs and trace ids. Keep business logic out of it. Examples: Envoy Gateway, Kong, AWS API Gateway.' },
    { id: 'idp', label: 'IdP / JWKS', sub: 'public signing keys', x: 2, y: 0, color: 'purple', info: 'The gateway caches the identity provider\'s public keys and verifies JWT signatures locally, so there is no network call per request. Keys rotate, so refresh the cache on an unknown key id (kid).' },
    { id: 'reg', label: 'Service registry', sub: 'healthy instances', x: 4, y: 0, color: 'teal', info: 'Consul, Eureka or Kubernetes EndpointSlices. Instances register (or are registered by the platform) and are removed when health checks or heartbeat TTLs fail.' },
    { id: 'o1', label: 'orders-1', sub: '10.0.1.17:8080', x: 4, y: 2, color: 'green', info: 'An ephemeral instance. Its IP changes on every reschedule, which is why callers must not hard-code addresses.' },
    { id: 'o2', label: 'orders-2', sub: '10.0.2.41:8080', x: 4, y: 3, color: 'green', exit: 6, info: 'Crashes in step 6. Until the registry notices, the gateway relies on retries and outlier detection to avoid it.' },
    { id: 'o3', label: 'orders-3', sub: 'new, autoscaled', x: 4, y: 4, color: 'green', enter: 5, info: 'Added by the autoscaler. It gets traffic only after it registers and passes its readiness check.' },
  ],
  edges: [
    { from: 'client', to: 'gw', label: 'HTTPS + JWT' },
    { from: 'gw', to: 'idp', label: 'cached keys', dashed: true },
    { from: 'gw', to: 'reg', label: 'resolve', dashed: true },
    { from: 'o1', to: 'reg', label: 'register + heartbeat', dashed: true },
    { from: 'gw', to: 'o1' }, { from: 'gw', to: 'o2' }, { from: 'gw', to: 'o3' },
  ],
  steps: [
    { caption: 'A client calls GET /orders/7 with a bearer token. The gateway terminates TLS: it is the single public entry point, so internal services are not exposed to the internet.', flows: [{ from: 'client', to: 'gw', label: 'GET /orders/7' }] },
    { caption: 'Edge concerns run once here instead of in every service: verify the JWT signature with cached JWKS keys, check coarse scopes, apply the rate limit for this API key.', flows: [{ from: 'idp', to: 'gw', label: 'keys (cached)' }], active: ['gw'] },
    { caption: 'Each instance registers on startup and heartbeats every few seconds. An instance that stops heartbeating (TTL 10 s) is dropped from the healthy set.', flows: [{ from: 'o1', to: 'reg', label: 'heartbeat' }, { from: 'o2', to: 'reg', label: 'heartbeat' }] },
    { caption: 'The gateway resolves "orders" to its healthy instances (watched and cached, not looked up per request) and picks one with least-request or power-of-two-choices balancing.', flows: [{ from: 'reg', to: 'gw', label: '[o1, o2]' }, { from: 'gw', to: 'o1', label: 'route' }] },
    { caption: 'Load rises and the autoscaler adds orders-3. It registers, passes readiness, and starts receiving traffic with no config change anywhere.', flows: [{ from: 'o3', to: 'reg', label: 'register' }, { from: 'gw', to: 'o3', label: 'route' }] },
    { caption: 'orders-2 crashes. Its heartbeats stop and the registry removes it after the TTL. Meanwhile the gateway retries idempotent requests on another instance and ejects it via outlier detection.', flows: [{ from: 'gw', to: 'o1' }, { from: 'gw', to: 'o3' }], active: ['reg'] },
    { caption: 'In Kubernetes this is built in: a Service name resolves via DNS, and EndpointSlices are updated from readiness probes. A service mesh does client-side discovery with mTLS and retries in sidecars.', active: ['reg', 'orders'] },
  ],
});

registerDiagram({
  id: 'sd-circuit-breaker',
  roadmap: 'system-design', module: 7, topic: 'Resilience Patterns: Timeouts, Retries, Circuit Breakers, Bulkheads',
  kind: 'graph',
  title: 'Circuit breaker state machine: closed, open, half-open',
  desc: 'A circuit breaker wraps calls to one dependency. When failures pass a threshold it opens and fails fast, which protects both the caller\'s resources and the struggling dependency. After a cool-down it lets a few trial calls through.',
  nodes: [
    { id: 'caller', label: 'Checkout svc', sub: 'caller', x: 0, y: 0, color: 'blue', info: 'Without a breaker, every request waits for the full timeout on a dead dependency. Goroutines, connections and memory pile up until the caller fails too: a cascading failure.' },
    { id: 'dep', label: 'Payments API', sub: 'dependency', x: 6, y: 0, color: 'purple', info: 'Degraded: slow responses and 5xx errors. Hammering it with requests and retries makes recovery harder.' },
    { id: 'closed', label: 'CLOSED', sub: 'calls pass through', x: 1, y: 2, shape: 'pill', color: 'green', info: 'Normal state. Counts failures and timeouts in a rolling window, for example the last 20 calls or 10 seconds.' },
    { id: 'open', label: 'OPEN', sub: 'fail fast', x: 5, y: 2, shape: 'pill', color: 'red', info: 'Every call is rejected immediately, in microseconds, with an error or a fallback: a cached value, a default, a "try later" message, or queueing the work.' },
    { id: 'half', label: 'HALF-OPEN', sub: 'a few trial calls', x: 3, y: 4, shape: 'pill', color: 'yellow', info: 'Lets a small number of requests through to probe the dependency. Everything else is still rejected, so a recovering service is not flooded.' },
  ],
  edges: [
    { from: 'caller', to: 'dep', label: 'calls via breaker' },
    { from: 'closed', to: 'open', label: 'failure rate > 50%' },
    { from: 'open', to: 'half', label: 'cool-down 30 s', curve: -50 },
    { id: 'h2o', from: 'half', to: 'open', label: 'trial fails', curve: -50 },
    { from: 'half', to: 'closed', label: 'trials succeed' },
  ],
  steps: [
    { caption: 'CLOSED: calls go through to the payments API. The breaker records each outcome; every call also has its own timeout, set from the dependency\'s p99.9 latency.', flows: [{ from: 'caller', to: 'dep', label: 'charge' }, { from: 'dep', to: 'caller', label: '200', color: 'green' }], active: ['closed'] },
    { caption: 'The dependency degrades: calls time out after 2 s or return 503. Without a breaker, threads and connections pile up waiting and the caller slows down too.', flows: [{ from: 'caller', to: 'dep', label: 'charge' }, { from: 'dep', to: 'caller', label: 'timeout', color: 'red' }], active: ['closed'] },
    { caption: 'The failure rate crosses the threshold (over 50% of at least 20 calls in the window). The breaker trips to OPEN. A minimum call count stops a single failure at low traffic from tripping it.', flows: [{ from: 'closed', to: 'open', label: 'trip' }] },
    { caption: 'OPEN: calls are rejected immediately with a fallback. The caller stays fast and the dependency gets room to recover instead of a retry storm.', flows: [{ from: 'open', to: 'caller', label: 'rejected (µs)', color: 'red' }], active: ['open'] },
    { caption: 'After the cool-down (say 30 s) the breaker moves to HALF-OPEN. It does not trust the dependency yet.', flows: [{ from: 'open', to: 'half', label: '30 s elapsed' }] },
    { caption: 'A few trial calls go through. If they succeed, the breaker closes and traffic resumes, ideally ramping up gradually.', flows: [{ from: 'caller', to: 'dep', label: 'trial' }, { from: 'half', to: 'closed', label: 'healthy' }] },
    { caption: 'If a trial fails, the breaker goes straight back to OPEN and restarts the timer. Use one breaker per dependency (a bulkhead), and combine with timeouts and retry budgets so retries are not multiplied at every layer.', flows: [{ from: 'half', to: 'open', label: 'still failing', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'sd-cqrs-event-sourcing',
  roadmap: 'system-design', module: 7, topic: 'Saga, CQRS & Event Sourcing',
  kind: 'graph',
  title: 'Event sourcing + CQRS: append events, project read models',
  desc: 'The write side stores what happened as an append-only event stream and enforces invariants. Projectors turn the stream into read models shaped for each query. Follow a withdrawal from command to eventually consistent query.',
  nodes: [
    { id: 'client', label: 'Client', icon: '💻', x: 0, y: 2, color: 'gray', info: 'Sends commands (intent: "withdraw 30") and queries (questions: "what is my balance?") to different endpoints.' },
    { id: 'cmd', label: 'Command handler', sub: 'enforces invariants', x: 2, y: 1, color: 'blue', info: 'Loads the aggregate by replaying its events (or a snapshot plus newer events), validates the command against current state, and appends new events. It never updates rows in place.' },
    { id: 'es', label: 'Event store', sub: 'append-only streams', x: 4, y: 1, shape: 'db', color: 'green', info: 'Stream "account-17": Opened, Deposited 100, Withdrew 20, ... Each append states the expected version, so concurrent writers to the same stream conflict instead of overwriting (optimistic concurrency).' },
    { id: 'proj', label: 'Projector', sub: 'subscribes to events', x: 6, y: 1, color: 'purple', info: 'Consumes events in order and updates read models idempotently, tracking its position in the stream. Rebuild a model by resetting the position to zero.' },
    { id: 'view', label: 'Balance view', sub: 'SQL table', x: 6, y: 3, shape: 'db', color: 'teal', info: 'A denormalised table with one row per account: exactly what the balance query needs, no joins.' },
    { id: 'search', label: 'Search index', sub: 'transactions by text', x: 4, y: 5, shape: 'db', color: 'teal', info: 'Another projection of the same events, optimised for a completely different query. CQRS lets each read model use the best store for its access pattern.' },
    { id: 'qry', label: 'Query API', sub: 'reads projections', x: 2, y: 3, color: 'blue', info: 'Read-only, so it can be scaled and cached separately from the write side.' },
  ],
  edges: [
    { from: 'client', to: 'cmd' }, { from: 'client', to: 'qry' },
    { from: 'cmd', to: 'es', both: true, label: 'append @v7' },
    { from: 'es', to: 'proj', label: 'subscribe' },
    { from: 'proj', to: 'view', label: 'upsert' }, { from: 'proj', to: 'search' },
    { from: 'qry', to: 'view' }, { from: 'qry', to: 'search' },
  ],
  steps: [
    { caption: 'The client sends the command "withdraw 30 from account 17". Commands express intent and can be rejected.', flows: [{ from: 'client', to: 'cmd', label: 'Withdraw 30' }] },
    { caption: 'The handler rebuilds current state by folding over the stream: Opened, Deposited 100, Withdrew 20, so the balance is 80 at version 7. Long streams use a snapshot plus the newer events.', flows: [{ from: 'es', to: 'cmd', label: 'replay → 80, v7' }] },
    { caption: 'The invariant (balance >= 30) holds, so it appends Withdrew 30 with expected version 7. A concurrent withdrawal that also read v7 gets a version conflict and retries with fresh state: no lost update.', flows: [{ from: 'cmd', to: 'es', label: 'Withdrew 30 @v7' }] },
    { caption: 'The projector receives the new event and updates both read models asynchronously. They lag by milliseconds to seconds: read models are eventually consistent.', flows: [{ from: 'es', to: 'proj', label: 'Withdrew 30' }, { from: 'proj', to: 'view', label: 'balance = 50' }, { from: 'proj', to: 'search', label: 'index txn' }] },
    { caption: 'Queries never touch the event log; they read projections built for them. To avoid "my withdrawal is missing", return the new state from the command or wait for the projection version.', flows: [{ from: 'client', to: 'qry', label: 'GET balance' }, { from: 'qry', to: 'view', label: 'SELECT' }] },
    { caption: 'Payoffs: a full audit trail, "state at 3 pm" queries, and new read models built by replaying history. Costs: event schema evolution forever, snapshots, GDPR erasure via crypto-shredding. Not for simple CRUD.', flows: [{ from: 'es', to: 'proj', label: 'replay all' }], active: ['view', 'search'] },
  ],
});

// ===== Module 8: Reliability =====================================================

registerDiagram({
  id: 'sd-multi-region-failover',
  roadmap: 'system-design', module: 8, topic: 'Redundancy, Failover & Multi-AZ / Multi-Region',
  kind: 'graph',
  title: 'Active-passive multi-region failover, and what it costs in data',
  desc: 'Region A serves all traffic and ships its database log to a warm standby in region B. When region A fails, detection, promotion and DNS switching decide the RTO; the replication lag at the moment of failure decides the RPO.',
  groups: [
    { id: 'ra', label: 'Region A (active)', x: 4, y: 0, w: 3, h: 2, color: 'green' },
    { id: 'rb', label: 'Region B (passive)', x: 4, y: 3, w: 3, h: 2, color: 'blue' },
  ],
  nodes: [
    { id: 'users', label: 'Users', icon: '👥', x: 0, y: 2, color: 'gray', info: 'Resolve the API hostname through DNS. Some clients and resolvers cache answers longer than the TTL says.' },
    { id: 'dns', label: 'Global DNS', sub: 'health-checked', x: 2, y: 2, color: 'purple', info: 'Route 53, Cloud DNS or a global load balancer with health checks. Failover routing returns region B only when region A\'s checks fail. Anycast global load balancers can shift traffic faster than DNS.' },
    { id: 'appA', label: 'App tier', sub: 'full capacity, 3 AZs', x: 4, y: 0.5, color: 'green', exit: 3, info: 'Already spread across three availability zones, so a single AZ failure never triggers a regional failover.' },
    { id: 'dbA', label: 'Primary DB', sub: 'all writes', x: 6, y: 0.5, shape: 'db', color: 'green', exit: 3, info: 'Multi-AZ inside the region (synchronous standby). Cross-region replication is asynchronous, because synchronous would add the cross-region round trip (tens of ms) to every commit.' },
    { id: 'appB', label: 'App tier', sub: 'warm, scaled down', x: 4, y: 3.5, color: 'blue', info: 'Runs at small size so it is known to work. It must be able to scale up fast, ideally pre-provisioned (static stability) rather than relying on a control plane during a regional crisis.' },
    { id: 'dbB', label: 'Standby DB', sub: 'async replica', x: 6, y: 3.5, shape: 'db', color: 'blue', info: 'Read-only replica in region B. Promotion makes it writable. Whatever it had not received at failure time is lost: that gap is the RPO.' },
  ],
  edges: [
    { from: 'users', to: 'dns' },
    { from: 'dns', to: 'appA' }, { from: 'dns', to: 'appB', dashed: true },
    { from: 'appA', to: 'dbA' }, { from: 'appB', to: 'dbB' },
    { from: 'dbA', to: 'dbB', label: 'async replication', dashed: true },
  ],
  steps: [
    { caption: 'Normal operation: DNS returns region A, which serves all reads and writes. Region B takes no user traffic.', flows: [{ from: 'users', to: 'dns', label: 'resolve' }, { from: 'dns', to: 'appA', label: 'region A' }, { from: 'appA', to: 'dbA', label: 'writes' }] },
    { caption: 'The primary ships its log to the standby in region B, typically under 1 s behind. That lag is the RPO you are actually buying, whatever the design doc says.', flows: [{ from: 'dbA', to: 'dbB', label: 'WAL stream' }], active: ['appB'] },
    { caption: 'Region A goes dark. Health checks fail several times in a row (about 30-90 s) before anything is declared down. Making detection too eager causes flapping on transient blips.', active: ['dns', 'dbB'] },
    { caption: 'Promote the standby to primary. Writes that had not yet replicated are lost. Fence the old primary (revoke credentials, block its network) so it cannot accept writes if region A comes back: split brain.', flows: [{ from: 'appB', to: 'dbB', label: 'promote' }], active: ['dbB'] },
    { caption: 'DNS now answers region B, but clients holding cached answers keep trying A until the TTL expires. Region B scales up to full load. RTO = detection + promotion + DNS propagation + scale-up.', flows: [{ from: 'users', to: 'dns', label: 'resolve' }, { from: 'dns', to: 'appB', label: 'region B' }, { from: 'appB', to: 'dbB', label: 'writes' }] },
    { caption: 'The passive path is rarely exercised, so it often fails when needed: run regular failover drills. Active-active removes the cold path but needs conflict handling or per-user home regions, and N+1 capacity in every region.', active: ['ra', 'rb'] },
  ],
});

// ===== Module 9: HLD classic problems ===========================================

registerDiagram({
  id: 'sd-url-shortener',
  roadmap: 'system-design', module: 9, problem: 'Design a URL shortener (TinyURL / bit.ly)',
  kind: 'graph',
  title: 'URL shortener: range-leased IDs on write, cache-first redirects on read',
  desc: 'A read-heavy system (about 100 reads per write) with a tiny write path. Follow a create request through key generation and storage, then a redirect served from cache, with click analytics kept off the hot path.',
  nodes: [
    { id: 'user', label: 'Browser', icon: '🌐', x: 0, y: 2, color: 'gray', info: 'Creates links rarely (about 40/s) and follows them often (4K/s average, 10K/s peak). Redirect p99 must stay under 50 ms.' },
    { id: 'api', label: 'Shortener API', sub: 'stateless pods', x: 2, y: 2, color: 'blue', info: 'Each pod holds a leased block of counter values in memory, so creating a code needs no coordination per request. Also enforces rate limits and runs URL abuse checks on create.' },
    { id: 'keys', label: 'Key range service', sub: 'leases 1M-ID blocks', x: 2, y: 0, color: 'purple', info: 'Hands out non-overlapping counter ranges (etcd or a DB row with an atomic increment). If a pod dies, the rest of its range is simply skipped: 3.5 trillion codes leave room to waste.' },
    { id: 'cache', label: 'Redis', sub: 'hot codes, LRU', x: 4, y: 1, shape: 'db', color: 'red', info: 'Link popularity is extremely skewed, so a few GB of cache serve the vast majority of redirects. Viral links can also be cached at the CDN edge.' },
    { id: 'db', label: 'Links store', sub: 'code → long_url', x: 4, y: 3, shape: 'db', color: 'green', info: 'A KV store (DynamoDB, Cassandra) or Postgres: links(code PK, long_url, owner_id, created_at, expires_at). About 3 TB over 5 years. Expiry by TTL; owner index for dashboards.' },
    { id: 'kafka', label: 'Kafka', sub: 'click events', x: 6, y: 2, shape: 'db', color: 'orange', info: 'Clicks are logged asynchronously so analytics never adds latency to a redirect.' },
    { id: 'olap', label: 'Analytics', sub: 'ClickHouse / OLAP', x: 6, y: 4, shape: 'db', color: 'teal', info: 'Aggregates clicks by link, country, referrer and time for owner dashboards.' },
  ],
  edges: [
    { from: 'user', to: 'api', both: true, label: 'POST / GET' },
    { from: 'api', to: 'keys', label: 'lease range' },
    { from: 'api', to: 'cache', both: true },
    { from: 'api', to: 'db', both: true },
    { from: 'api', to: 'kafka', label: 'click event', dashed: true },
    { from: 'kafka', to: 'olap' },
  ],
  steps: [
    { caption: 'Write path: POST /urls with the long URL. The API pod takes the next value from the counter range it leased, say 5,000,123. Pods lease a fresh block of 1M IDs only when theirs runs out.', flows: [{ from: 'user', to: 'api', label: 'POST long URL' }, { from: 'api', to: 'keys', label: 'lease (rare)' }] },
    { caption: 'The counter goes through a bijective scramble and is encoded as 7 base62 characters (62^7 ≈ 3.5 trillion codes), for example aZ3k9Qx. Counters never collide, and the scramble stops people enumerating links.', active: ['api'] },
    { caption: 'Store code → long URL with a conditional insert, then return the short link. Write load is about 40/s, so the write path is trivial; the interview is about the read path.', flows: [{ from: 'api', to: 'db', label: 'PUT aZ3k9Qx' }, { from: 'api', to: 'user', label: 'sho.rt/aZ3k9Qx' }] },
    { caption: 'Read path: GET /aZ3k9Qx. The API checks Redis first; popular links hit in under a millisecond.', flows: [{ from: 'user', to: 'api', label: 'GET /aZ3k9Qx' }, { from: 'api', to: 'cache', label: 'GET' }, { from: 'cache', to: 'api', label: 'hit', color: 'green' }] },
    { caption: 'On a miss, read the links store and fill the cache. Cache "not found" briefly too, so scanners probing random codes do not hammer the database.', flows: [{ from: 'api', to: 'db', label: 'miss → read' }, { from: 'api', to: 'cache', label: 'SET' }] },
    { caption: 'Respond 302 with Location: the long URL. A 301 would be cached by browsers, cutting load but losing click tracking. The click event goes to Kafka asynchronously for analytics.', flows: [{ from: 'api', to: 'user', label: '302 redirect' }, { from: 'api', to: 'kafka', label: 'click' }, { from: 'kafka', to: 'olap' }] },
  ],
});

registerDiagram({
  id: 'sd-news-feed',
  roadmap: 'system-design', module: 9, problem: 'Design a news feed (Twitter / Instagram home timeline)',
  kind: 'graph',
  title: 'News feed: hybrid fan-out on write, merge and hydrate on read',
  desc: 'Precompute feeds for normal authors (push), pull celebrity posts at read time, and store only post IDs in feeds. Follow a post from author to follower feeds, then a feed load that merges, hydrates and returns in under 200 ms.',
  nodes: [
    { id: 'author', label: 'Author', icon: '✍️', x: 0, y: 0, color: 'gray', info: '600M posts/day, about 7K writes/s. Most authors have around 200 followers; a few have 100M.' },
    { id: 'postsvc', label: 'Post service', sub: 'Snowflake IDs', x: 2, y: 0, color: 'blue', info: 'Assigns a time-sortable 64-bit ID so feeds can be sorted and paginated by ID. Media goes to object storage and a CDN; only metadata is stored here.' },
    { id: 'postsdb', label: 'Posts DB', sub: 'sharded by author', x: 4, y: 0, shape: 'db', color: 'green', info: 'posts(post_id, author_id, body, media, created_at), sharded by author_id so "recent posts by X" is a single-shard query. An outbox row is written in the same transaction.' },
    { id: 'graph', label: 'Social graph', sub: 'followers_of', x: 6, y: 0, shape: 'db', color: 'green', info: 'Follow edges stored in both directions (followers_of, following_of), since fan-out needs one and feed reads need the other.' },
    { id: 'kafka', label: 'Kafka', sub: 'new-post events', x: 4, y: 2, shape: 'db', color: 'orange', info: 'Decouples posting from fan-out. Posting returns as soon as the post is stored; fan-out lags by seconds, which the requirements allow.' },
    { id: 'fanout', label: 'Fan-out workers', sub: 'push to followers', x: 6, y: 2, color: 'purple', info: 'For each new post: page through followers and push the post ID into each feed. They skip authors over a follower threshold (say 100K) and users inactive for weeks.' },
    { id: 'feeds', label: 'Feed cache', sub: 'Redis list per user', x: 4, y: 4, shape: 'db', color: 'red', info: 'feed:{user_id} is a list of post IDs capped at about 800 entries. IDs only, so edits and deletes show up at hydration and memory stays small.' },
    { id: 'reader', label: 'Reader', icon: '📱', x: 0, y: 4, color: 'gray', info: '300M DAU loading the feed about 30 times a day: about 100K reads/s. Feed load p99 must be under 200 ms.' },
    { id: 'feedsvc', label: 'Feed service', sub: 'merge, rank, hydrate', x: 2, y: 4, color: 'blue', info: 'Reads the precomputed feed, merges in recent posts from followed celebrities, optionally ranks, hydrates IDs to content, and returns a page with a cursor.' },
    { id: 'pcache', label: 'Post + user cache', sub: 'hydrate IDs', x: 2, y: 6, shape: 'db', color: 'red', info: 'Multi-get of post bodies and author profiles. Hot posts are replicated across cache shards or held in a local L1 to avoid hot keys.' },
  ],
  edges: [
    { from: 'author', to: 'postsvc', label: 'POST' },
    { from: 'postsvc', to: 'postsdb', label: 'INSERT' },
    { from: 'postsdb', to: 'kafka', label: 'outbox → CDC' },
    { from: 'kafka', to: 'fanout' },
    { from: 'fanout', to: 'graph', label: 'followers' },
    { from: 'fanout', to: 'feeds', label: 'LPUSH post_id' },
    { from: 'reader', to: 'feedsvc', label: 'GET /feed' },
    { from: 'feedsvc', to: 'feeds', label: 'LRANGE' },
    { from: 'feedsvc', to: 'postsdb', label: 'celebrity pull', dashed: true },
    { from: 'feedsvc', to: 'pcache', label: 'multi-get' },
  ],
  steps: [
    { caption: 'Write path: an author posts. The post service assigns a Snowflake ID and stores the post with an outbox row in one transaction, then returns. The author does not wait for fan-out.', flows: [{ from: 'author', to: 'postsvc', label: 'new post' }, { from: 'postsvc', to: 'postsdb', label: 'post + outbox' }] },
    { caption: 'CDC publishes a new-post event to Kafka, partitioned by author. Fan-out workers consume it.', flows: [{ from: 'postsdb', to: 'kafka', label: 'NewPost' }, { from: 'kafka', to: 'fanout', label: 'NewPost' }] },
    { caption: 'The workers page through the author\'s followers. If the author has more than about 100K followers, they stop here: pushing to 100M feeds would mean 100M writes for one post.', flows: [{ from: 'fanout', to: 'graph', label: 'followers_of' }] },
    { caption: 'For a normal author, push the post ID into each follower\'s feed list and trim it to 800 entries. With 200 followers on average that is about 1.4M list inserts per second at peak, all cheap.', flows: [{ from: 'fanout', to: 'feeds', label: 'LPUSH × 200' }] },
    { caption: 'Read path: a reader opens the app. The feed service reads the first page of post IDs from the precomputed list in one fast lookup.', flows: [{ from: 'reader', to: 'feedsvc', label: 'GET /feed' }, { from: 'feedsvc', to: 'feeds', label: 'LRANGE 0 50' }] },
    { caption: 'Merge in recent posts from the few celebrities the reader follows, fetched at read time (fan-out on read) and cached per celebrity. This hybrid handles both extremes of follower count.', flows: [{ from: 'feedsvc', to: 'postsdb', label: 'celebrity posts' }] },
    { caption: 'Hydrate the IDs with a multi-get from the post and user caches, optionally rank, and return the page with a cursor. A returning inactive user has no precomputed feed, so it is rebuilt by pull on first load.', flows: [{ from: 'feedsvc', to: 'pcache', label: 'multi-get' }, { from: 'feedsvc', to: 'reader', label: 'page + cursor' }] },
  ],
});

registerDiagram({
  id: 'sd-chat',
  roadmap: 'system-design', module: 9, problem: 'Design a chat system (WhatsApp / Messenger)',
  kind: 'graph',
  title: 'Chat: persist, sequence, route to the recipient\'s gateway, or push',
  desc: 'Stateful WebSocket gateways hold the connections; stateless services do the work. Follow one message from Alice: server-side sequencing, persistence before the "sent" tick, routing through a session registry, and push plus sync when Bob is offline.',
  nodes: [
    { id: 'alice', label: 'Alice', icon: '📱', x: 0, y: 1, color: 'gray', info: 'Generates a client_msg_id for each message so a resend after a reconnect is deduplicated.' },
    { id: 'gw1', label: 'WS gateway 1', sub: '~500K connections', x: 2, y: 1, color: 'blue', info: 'Holds long-lived WebSocket connections and does little else. Around 100M concurrent connections means hundreds of gateway nodes. Heartbeats detect dead peers and keep NAT mappings open.' },
    { id: 'chat', label: 'Chat service', sub: 'sequence + route', x: 4, y: 1, color: 'purple', info: 'Assigns a per-conversation sequence number (a single writer per conversation, for example via a Kafka partition keyed by conversation_id), persists, then routes. Client timestamps are never trusted for ordering.' },
    { id: 'store', label: 'Messages', sub: 'Cassandra / Scylla', x: 6, y: 1, shape: 'db', color: 'green', info: 'messages(conversation_id, bucket, seq, ...) with conversation_id plus time bucket as partition key and seq as clustering key: one partition read returns a page of history in order. About 2 TB/day.' },
    { id: 'reg', label: 'Session registry', sub: 'user → gateway', x: 6, y: 3, shape: 'db', color: 'red', info: 'Maps each user device to the gateway holding its connection, with a TTL refreshed by heartbeats. A stale entry just means a failed delivery, followed by push and sync.' },
    { id: 'gw2', label: 'WS gateway 2', sub: 'Bob\'s connection', x: 2, y: 4, color: 'blue', info: 'Another gateway node. Any gateway can deliver to any user its registry entry points to.' },
    { id: 'bob', label: 'Bob', icon: '📱', x: 0, y: 4, color: 'gray', info: 'Each device keeps a cursor (last seq seen per conversation) and syncs from it on reconnect, which also covers multi-device history.' },
    { id: 'push', label: 'Push service', sub: 'APNs / FCM', x: 4, y: 5, color: 'orange', info: 'Used when no device has a live connection. The push only wakes the app; content is then fetched through sync (or sent end-to-end encrypted in the payload).' },
  ],
  edges: [
    { from: 'alice', to: 'gw1', both: true, label: 'WebSocket' },
    { from: 'gw1', to: 'chat', both: true, label: 'send / ack' },
    { from: 'chat', to: 'store', label: 'persist' },
    { from: 'chat', to: 'reg', label: 'where is Bob?' },
    { from: 'chat', to: 'gw2', label: 'deliver' },
    { from: 'gw2', to: 'bob', both: true },
    { from: 'chat', to: 'push', label: 'offline' },
    { from: 'push', to: 'bob', dashed: true },
  ],
  steps: [
    { caption: 'Write path: Alice sends "hi" on her open WebSocket with a client_msg_id. Gateway 1 forwards it to the chat service.', flows: [{ from: 'alice', to: 'gw1', label: 'hi (cmid 77)' }, { from: 'gw1', to: 'chat', label: 'hi' }] },
    { caption: 'The chat service assigns the next sequence number for this conversation (42) and persists the message before acknowledging. Server-side sequencing gives one order that every device agrees on.', flows: [{ from: 'chat', to: 'store', label: 'seq 42' }] },
    { caption: 'Only after the write is durable does Alice get the "sent" tick. If the chat service crashes before this, Alice resends and the client_msg_id prevents a duplicate.', flows: [{ from: 'chat', to: 'gw1', label: 'ack seq 42' }, { from: 'gw1', to: 'alice', label: 'sent ✓' }] },
    { caption: 'Read path: the chat service looks up Bob\'s devices in the session registry and finds his phone connected to gateway 2.', flows: [{ from: 'chat', to: 'reg', label: 'bob?' }, { from: 'reg', to: 'chat', label: 'gateway 2' }] },
    { caption: 'The message is delivered through gateway 2. Bob\'s app acknowledges and Alice sees the "delivered" double tick; a read receipt follows the same path later.', flows: [{ from: 'chat', to: 'gw2', label: 'seq 42' }, { from: 'gw2', to: 'bob', label: 'hi' }] },
    { caption: 'If Bob is offline there is no registry entry: send a push notification instead. When the app reconnects it syncs from its cursor, "give me everything after seq 41", so nothing is missed.', flows: [{ from: 'chat', to: 'push', label: 'no session' }, { from: 'push', to: 'bob', label: 'wake up' }, { from: 'bob', to: 'gw2', label: 'sync after 41' }] },
    { caption: 'Things interviewers probe: a deploy drops 500K connections at once, so drain gateways slowly and make clients reconnect with jittered backoff. Groups of up to 500 fan out per member; presence is fanned out lazily to visible contacts only.', active: ['gw1', 'gw2', 'reg'] },
  ],
});

registerDiagram({
  id: 'sd-distributed-rate-limiter',
  roadmap: 'system-design', module: 9, problem: 'Design a distributed rate limiter',
  kind: 'graph',
  title: 'Distributed rate limiter: one shared bucket per key, many gateways',
  desc: 'Fifty gateway nodes must enforce the same limit for an API key, so the bucket state is shared in Redis and updated atomically by a Lua script. Follow an allowed request and a throttled one, then the failure-mode decision.',
  nodes: [
    { id: 'client', label: 'API client', sub: 'key: acme-prod', x: 0, y: 2, color: 'gray', info: 'Its requests are spread across many gateway nodes by the load balancer, so no single node sees all of its traffic.' },
    { id: 'gw1', label: 'Gateway node 1', sub: 'limiter middleware', x: 2, y: 1, color: 'blue', info: 'Runs the limiter before routing. The overhead budget is about 2 ms, of which the Redis round trip is roughly 0.5 ms within the same zone.' },
    { id: 'gw2', label: 'Gateway node 2', sub: 'limiter middleware', x: 2, y: 3, color: 'blue', info: 'One of about 50 nodes. If each node enforced the limit locally it would need limit / N per node, which is inaccurate when the load balancer spreads traffic unevenly.' },
    { id: 'rules', label: 'Rules service', sub: 'cached config', x: 4, y: 0, color: 'purple', info: 'Limits per tier and key, such as 100/s and 10K/day. Pushed to or polled by gateways and cached locally: never looked up per request.' },
    { id: 'redis', label: 'Redis Cluster', sub: 'Lua token bucket', x: 4, y: 4, shape: 'db', color: 'red', info: 'Key rl:{acme-prod}:per-sec holds tokens and last_refill_ms, with a TTL. The hash tag {acme-prod} puts all of a key\'s rules in one slot so one script can check them all. 10M active keys × ~100 B ≈ 1 GB.' },
    { id: 'backend', label: 'Backend API', x: 6, y: 2, color: 'green', info: 'Protected from overload and from one tenant starving others.' },
  ],
  edges: [
    { from: 'client', to: 'gw1' }, { from: 'client', to: 'gw2' },
    { from: 'gw1', to: 'rules', dashed: true },
    { from: 'gw1', to: 'redis' },
    { from: 'gw2', to: 'redis', label: 'EVALSHA bucket.lua' },
    { from: 'gw1', to: 'backend' }, { from: 'gw2', to: 'backend' },
  ],
  steps: [
    { caption: 'A request from key acme-prod lands on gateway 1. The limits for its tier (100/s and 10K/day) come from the locally cached rules: no network call.', flows: [{ from: 'client', to: 'gw1', label: 'GET /v1/items' }, { from: 'rules', to: 'gw1', label: 'rules (cached)' }] },
    { caption: 'Gateway 1 runs one atomic Lua script in Redis: refill tokens for the elapsed time using Redis TIME (not the gateway\'s clock), take a token if one is available, return the remaining count. Atomic means no read-modify-write race between gateways.', flows: [{ from: 'gw1', to: 'redis', label: 'take 1 token' }, { from: 'redis', to: 'gw1', label: 'ok, 37 left', color: 'green' }] },
    { caption: 'Allowed: forward to the backend and add X-RateLimit-Limit and X-RateLimit-Remaining headers so clients can pace themselves.', flows: [{ from: 'gw1', to: 'backend', label: 'forward' }] },
    { caption: 'A burst from the same key hits gateway 2. It runs the same script against the same Redis key, so the limit holds across all 50 nodes.', flows: [{ from: 'client', to: 'gw2', label: 'burst' }, { from: 'gw2', to: 'redis', label: 'take 1 token' }, { from: 'redis', to: 'gw2', label: '0 left', color: 'red' }] },
    { caption: 'Denied: respond 429 Too Many Requests with Retry-After, without touching the backend. Count throttles per key in metrics; a spike usually means a client bug or abuse.', flows: [{ from: 'gw2', to: 'client', label: '429 Retry-After: 1', color: 'red' }] },
    { caption: 'Trade-offs to state: if Redis is slow or down, fail open (with a coarse local limit) to protect availability, or fail closed to protect the backend. A huge tenant can lease batches of tokens to cut Redis calls, trading a little accuracy.', active: ['gw1', 'gw2', 'redis'] },
  ],
});

registerDiagram({
  id: 'sd-video-streaming',
  roadmap: 'system-design', module: 9, problem: 'Design a video streaming platform (YouTube / Netflix)',
  kind: 'graph',
  title: 'Video platform: upload and transcode pipeline, CDN-served playback',
  desc: 'Uploads bypass the app servers and feed a parallel transcoding pipeline that produces small segments at many bitrates. Playback is mostly a CDN problem: the player fetches segments from the nearest edge and adapts bitrate as it goes.',
  nodes: [
    { id: 'creator', label: 'Creator', icon: '🎥', x: 0, y: 0, color: 'gray', info: 'Uploads large files (GBs) over unreliable networks, so uploads must be resumable in parts.' },
    { id: 'upload', label: 'Upload API', sub: 'pre-signed URLs', x: 2, y: 0, color: 'blue', info: 'Authorises the upload, creates the video record (status UPLOADING) and returns pre-signed multipart URLs. The bytes never pass through it.' },
    { id: 'raw', label: 'Raw bucket', sub: 'object storage', x: 4, y: 0, shape: 'db', color: 'green', info: 'Keeps the original source file so it can be re-encoded later with better codecs (AV1) without asking the creator again.' },
    { id: 'tx', label: 'Transcode DAG', sub: 'chunk·encode·package', x: 6, y: 0, color: 'purple', info: 'Splits the source into GOP-aligned chunks, encodes them in parallel on an autoscaled (often spot) fleet across a ladder of 240p to 4K and H.264, VP9 or AV1, then packages HLS/DASH segments, manifests, thumbnails and DRM.' },
    { id: 'meta', label: 'Metadata DB', sub: 'videos, renditions', x: 4, y: 2, shape: 'db', color: 'teal', info: 'videos(id, owner, title, status, duration) and renditions(video_id, resolution, codec, manifest_url). Small, read-heavy, heavily cached.' },
    { id: 'origin', label: 'Origin bucket', sub: 'segments + manifests', x: 6, y: 2, shape: 'db', color: 'green', info: 'The processed output: 2-6 second segments per rendition. Storage is several times the source size, which is why long-tail videos may be transcoded just in time.' },
    { id: 'play', label: 'Playback API', sub: 'signed manifest URL', x: 2, y: 2, color: 'blue', info: 'Checks entitlement and region, picks renditions for the device, and returns a short-lived signed manifest URL so the CDN can enforce access.' },
    { id: 'viewer', label: 'Viewer', icon: '📺', x: 0, y: 4, color: 'gray', info: 'The player runs the adaptive bitrate (ABR) algorithm: it measures throughput and buffer level and picks the bitrate for each next segment.' },
    { id: 'cdn', label: 'CDN edge', sub: '+ ISP caches', x: 6, y: 4, color: 'orange', info: '10M concurrent viewers at 5 Mbps is 50 Tbps of egress, which only a CDN can serve. Netflix places its own Open Connect caches inside ISPs and pre-fills them off-peak.' },
  ],
  edges: [
    { from: 'creator', to: 'upload', label: 'start upload' },
    { from: 'creator', to: 'raw', curve: 90, label: 'multipart PUT' },
    { from: 'raw', to: 'tx', label: 'object created' },
    { from: 'tx', to: 'origin', label: 'HLS / DASH' },
    { from: 'tx', to: 'meta', label: 'READY' },
    { from: 'viewer', to: 'play' },
    { from: 'play', to: 'meta', label: 'lookup' },
    { from: 'viewer', to: 'cdn', label: 'segments (ABR)' },
    { from: 'cdn', to: 'origin', label: 'miss → shield' },
  ],
  steps: [
    { caption: 'Write path: the creator asks the upload API to start an upload. It creates the video record and returns pre-signed multipart URLs.', flows: [{ from: 'creator', to: 'upload', label: 'start' }, { from: 'upload', to: 'creator', label: 'signed URLs' }] },
    { caption: 'The client uploads parts directly to object storage, in parallel and resumable: a dropped connection retries one part, not the whole file. App servers never carry video bytes.', flows: [{ from: 'creator', to: 'raw', label: 'parts 1..N' }] },
    { caption: 'The object-created event starts the transcoding DAG: split into chunks, encode every chunk at every rung of the bitrate ladder in parallel, so a 1-hour video finishes in minutes rather than hours.', flows: [{ from: 'raw', to: 'tx', label: 'source.mp4' }] },
    { caption: 'Segments and manifests land in the origin bucket and the renditions are recorded with status READY. Popular new titles can be pushed to edges before anyone asks.', flows: [{ from: 'tx', to: 'origin', label: 'segments' }, { from: 'tx', to: 'meta', label: 'READY' }] },
    { caption: 'Read path: the viewer presses play. The playback API checks access and returns a signed manifest URL. Startup must be under 2 s, so this call is cached and fast.', flows: [{ from: 'viewer', to: 'play', label: 'play v123' }, { from: 'play', to: 'meta', label: 'renditions' }, { from: 'play', to: 'viewer', label: 'manifest URL' }] },
    { caption: 'The player fetches segments from the nearest CDN edge and picks a bitrate per segment from measured throughput and buffer. It starts low for a fast start, then climbs.', flows: [{ from: 'viewer', to: 'cdn', label: 'seg 1 @ 720p' }] },
    { caption: 'A miss at the edge goes to an origin shield, then to the origin bucket, so hundreds of edges cause one origin fetch. Long-tail content has low hit rates, which is the main cost lever.', flows: [{ from: 'cdn', to: 'origin', label: 'miss' }, { from: 'cdn', to: 'viewer', label: 'seg 2 @ 1080p' }] },
  ],
});

registerDiagram({
  id: 'sd-ride-sharing',
  roadmap: 'system-design', module: 9, problem: 'Design a ride-sharing service (Uber / Lyft)',
  kind: 'graph',
  title: 'Ride sharing: in-memory geo index for writes, k-ring dispatch for reads',
  desc: 'Millions of drivers report their location every few seconds; riders need a nearby driver in seconds. Keep only the latest positions in memory, indexed by cell, and make the driver assignment atomic so no driver gets two trips.',
  nodes: [
    { id: 'driver', label: 'Driver app', icon: '🚗', x: 0, y: 0, color: 'gray', info: 'Sends GPS every 4 s over a persistent connection and receives trip offers on it.' },
    { id: 'loc', label: 'Location service', sub: 'persistent conns', x: 2, y: 0, color: 'blue', info: '5M active drivers every 4 s is about 1.25M location writes per second, sharded by city. Each update is a small overwrite, not an insert.' },
    { id: 'geo', label: 'Geo index', sub: 'H3 cells, in memory', x: 4, y: 0, shape: 'db', color: 'red', info: 'Latest position and status per driver, indexed by H3 (or S2/geohash) cell, in Redis or an in-process index, sharded by city. Entries expire after about 30 s without an update. After a failover it is rebuilt from fresh pings within seconds.' },
    { id: 'kafka', label: 'Kafka', sub: 'location history', x: 2, y: 2, shape: 'db', color: 'orange', info: 'Every ping is streamed here for trip receipts, ETA model training and surge pricing per cell. Persisting every ping in the OLTP database would be far too expensive.' },
    { id: 'dispatch', label: 'Dispatch service', sub: 'search, rank, offer', x: 4, y: 2, color: 'purple', info: 'Finds candidate drivers near the pickup, ranks them by real road ETA, and offers the trip to one driver at a time with a timeout. Some systems batch-match every few seconds for a better global assignment.' },
    { id: 'eta', label: 'Routing / ETA', sub: 'road graph', x: 6, y: 2, color: 'teal', info: 'Straight-line distance lies (rivers, one-way streets), so candidates are ranked by road ETA from a routing engine.' },
    { id: 'rider', label: 'Rider app', icon: '🙋', x: 0, y: 4, color: 'gray', info: 'Requests a ride and then watches the driver approach in real time.' },
    { id: 'trip', label: 'Trip service', sub: 'state machine', x: 2, y: 4, color: 'blue', info: 'REQUESTED → MATCHED → ARRIVED → IN_TRIP → COMPLETED (or CANCELLED). Every transition uses a version check so concurrent updates cannot corrupt a trip.' },
    { id: 'tripdb', label: 'Trips DB', sub: 'SQL, by region', x: 4, y: 4, shape: 'db', color: 'green', info: 'Strongly consistent storage for money and state: trips(trip_id, rider_id, driver_id, state, fare, version). About 230 trips/s, so correctness matters more than throughput.' },
  ],
  edges: [
    { from: 'driver', to: 'loc', both: true, label: 'GPS / 4 s' },
    { from: 'loc', to: 'geo', label: 'overwrite' },
    { from: 'loc', to: 'kafka', label: 'history' },
    { from: 'dispatch', to: 'geo', both: true, label: 'k-ring + CAS' },
    { from: 'dispatch', to: 'eta', label: 'ETAs' },
    { from: 'rider', to: 'trip', label: 'request' },
    { from: 'trip', to: 'tripdb' },
    { from: 'trip', to: 'dispatch', label: 'find driver' },
    { from: 'dispatch', to: 'driver', dashed: true },
  ],
  steps: [
    { caption: 'Write path: every active driver sends a GPS update every 4 s over a persistent connection, about 1.25M writes per second worldwide, sharded by city.', flows: [{ from: 'driver', to: 'loc', label: 'lat, lng' }] },
    { caption: 'Each update overwrites the driver\'s entry in the in-memory geo index under its H3 cell. Only the latest position matters for matching, and entries expire if a driver goes silent.', flows: [{ from: 'loc', to: 'geo', label: 'cell 8928308' }] },
    { caption: 'The full history is streamed to Kafka for receipts, analytics and surge pricing, keeping the hot path in memory.', flows: [{ from: 'loc', to: 'kafka', label: 'ping' }] },
    { caption: 'Read path: a rider requests a ride. The trip service creates the trip in REQUESTED state in the strongly consistent trips database.', flows: [{ from: 'rider', to: 'trip', label: 'pickup, dropoff' }, { from: 'trip', to: 'tripdb', label: 'REQUESTED' }] },
    { caption: 'Dispatch searches the pickup cell and its k-ring of neighbouring cells for available drivers, widening the ring if too few are found. Hexagons make every neighbour the same distance away.', flows: [{ from: 'trip', to: 'dispatch', label: 'find driver' }, { from: 'dispatch', to: 'geo', label: 'k-ring(2)' }] },
    { caption: 'Candidates are ranked by road ETA from the routing service, not by straight-line distance.', flows: [{ from: 'dispatch', to: 'eta', label: '8 candidates' }, { from: 'eta', to: 'dispatch', label: 'ETAs' }] },
    { caption: 'Lock the best driver atomically: compare-and-set status from available to offered. Without it two dispatchers could offer one driver two trips. Then send the offer with a 10 s timeout.', flows: [{ from: 'dispatch', to: 'geo', label: 'CAS → offered' }, { from: 'dispatch', to: 'driver', label: 'offer' }] },
    { caption: 'The driver accepts; the trip moves to MATCHED with a version check, and the rider sees the driver approaching. If the driver declines or times out, release the lock and offer the next candidate.', flows: [{ from: 'driver', to: 'dispatch', label: 'accept' }, { from: 'dispatch', to: 'trip', label: 'MATCHED' }, { from: 'trip', to: 'rider', label: 'driver en route' }] },
  ],
});

registerDiagram({
  id: 'sd-payment-system',
  roadmap: 'system-design', module: 9, problem: 'Design a payment system',
  kind: 'graph',
  title: 'Payment system: idempotent state machine, PSP, ledger, reconciliation',
  desc: 'Low volume, extreme correctness. Follow one card payment through idempotent creation, authorisation with an external PSP, double-entry ledger postings, asynchronous webhooks, and the daily reconciliation that catches anything the rest missed.',
  nodes: [
    { id: 'client', label: 'Checkout', sub: 'merchant site', icon: '🛒', x: 0, y: 1, color: 'gray', info: 'Card details are entered in PSP-hosted fields and turned into a token, so the raw card number never touches your servers (PCI-DSS scope stays small).' },
    { id: 'api', label: 'Payment API', sub: 'idempotency keys', x: 2, y: 1, color: 'blue', info: 'Requires an Idempotency-Key per payment attempt; a retry returns the stored result instead of charging twice.' },
    { id: 'paysvc', label: 'Payment service', sub: 'state machine', x: 4, y: 1, color: 'purple', info: 'CREATED → AUTHORIZED → CAPTURED → SETTLED, or FAILED / REFUNDED. Transitions are conditional updates on a version column, so duplicate or out-of-order events cannot move a payment backwards.' },
    { id: 'psp', label: 'Card processor', sub: 'PSP: Stripe, Adyen', x: 6, y: 1, color: 'orange', info: 'External and occasionally slow or down. Pass your payment id as the PSP idempotency key. Some companies route between two PSPs for failover and cost.' },
    { id: 'ledger', label: 'Ledger', sub: 'double-entry, append', x: 2, y: 3, shape: 'db', color: 'green', info: 'ledger_entries(txn_id, account_id, direction, amount_minor). Every transaction\'s debits equal its credits. Entries are never updated: corrections are new reversing entries. Amounts are integers in minor units, never floats.' },
    { id: 'paydb', label: 'Payments DB', sub: 'status + version', x: 4, y: 3, shape: 'db', color: 'teal', info: 'payments(id, idempotency_key UNIQUE, merchant_id, amount_minor, currency, status, psp_ref, version). Strongly consistent SQL, sharded by merchant if needed.' },
    { id: 'webhook', label: 'Webhook handler', sub: 'verify sig, dedupe', x: 6, y: 3, color: 'blue', info: 'Verifies the PSP signature, deduplicates by event id, and applies the state transition. It must be idempotent: PSPs deliver webhooks at least once and not always in order.' },
    { id: 'recon', label: 'Reconciliation', sub: 'daily batch job', x: 4, y: 5, color: 'red', info: 'Compares the PSP settlement file line by line with the ledger and payments table. Mismatches ("breaks") raise alerts and go to a manual review queue.' },
  ],
  edges: [
    { from: 'client', to: 'api', label: 'POST + key' },
    { from: 'api', to: 'paysvc' },
    { from: 'paysvc', to: 'psp', both: true, label: 'authorize' },
    { from: 'paysvc', to: 'paydb', label: 'transitions' },
    { from: 'paysvc', to: 'ledger', label: 'post entries' },
    { from: 'psp', to: 'webhook', label: 'webhooks' },
    { from: 'webhook', to: 'paydb', label: 'CAPTURED' },
    { from: 'recon', to: 'ledger', label: 'compare' },
    { from: 'recon', to: 'psp', dashed: true },
  ],
  steps: [
    { caption: 'Write path: checkout sends POST /payments with an Idempotency-Key and a card token. The payment row is created as CREATED; the UNIQUE key makes a duplicate request return the existing payment.', flows: [{ from: 'client', to: 'api', label: '$80, key K9' }, { from: 'api', to: 'paysvc' }, { from: 'paysvc', to: 'paydb', label: 'CREATED' }] },
    { caption: 'Authorise with the PSP, passing our payment id as its idempotency key. On success, move the payment to AUTHORIZED with a version-checked update.', flows: [{ from: 'paysvc', to: 'psp', label: 'authorize' }, { from: 'psp', to: 'paysvc', label: 'approved' }, { from: 'paysvc', to: 'paydb', label: 'AUTHORIZED' }] },
    { caption: 'The hard case: the PSP call times out. The money may or may not have moved, so the state is UNKNOWN. Never blindly retry a charge: query the PSP by our reference first, then continue.', flows: [{ from: 'paysvc', to: 'psp', label: 'GET status?', color: 'orange' }] },
    { caption: 'Record the money movement as balanced double-entry postings, for example debit "PSP receivable" and credit "merchant payable" by 8000 cents. The ledger, not the status column, is the financial source of truth.', flows: [{ from: 'paysvc', to: 'ledger', label: 'debit = credit' }] },
    { caption: 'Capture and settlement are confirmed asynchronously. The webhook handler verifies the signature, deduplicates by event id and applies the transition only if the version still matches.', flows: [{ from: 'psp', to: 'webhook', label: 'captured evt' }, { from: 'webhook', to: 'paydb', label: 'CAPTURED' }] },
    { caption: 'Every day, reconciliation matches the PSP settlement file against the ledger. Missed webhooks, double captures and fee differences show up here and go to an alert and a manual queue.', flows: [{ from: 'recon', to: 'psp', label: 'settlement file' }, { from: 'recon', to: 'ledger', label: 'match entries' }] },
    { caption: 'Design rules interviewers expect: integers in minor units, append-only ledger with reversing entries, idempotency at every hop, events published via an outbox, and a circuit breaker with fallback PSP routing.', active: ['ledger', 'paydb', 'paysvc'] },
  ],
});

