registerDiagram({
  id: 'sd-lld-parking-lot',
  roadmap: 'system-design', module: 11, problem: 'Parking lot',
  kind: 'graph',
  title: 'Parking lot LLD: classes, relationships and the Park flow',
  desc: 'A class diagram drawn as a graph: composition from lot to levels to spots, a pluggable pricing strategy, an observer for display boards and a single lock for allocation. Step through Park and Exit to see which object does what.',
  nodes: [
    { id: 'pricing', label: 'PricingStrategy', sub: 'interface: Fee()', x: 1, y: 0, color: 'purple', info: 'type PricingStrategy interface { Fee(t Ticket, now time.Time) Money }. The lot depends on this interface, not on a concrete pricing rule (dependency inversion).' },
    { id: 'lot', label: 'ParkingLot', sub: 'mutex, Park, Exit', x: 3, y: 0, color: 'blue', info: 'The facade and aggregate root. Park(v) and Exit(ticketID) run under one mutex (or one per level) so two gates can never assign the same spot. Exit is idempotent: paying twice for one ticket is rejected.' },
    { id: 'display', label: 'DisplayBoard', sub: 'observer', x: 5, y: 0, color: 'teal', info: 'Subscribes to spot-count changes. Notify asynchronously or with a buffered channel so a slow display cannot block parking.' },
    { id: 'hourly', label: 'HourlyPricing', sub: 'implements', x: 0, y: 2, color: 'purple', info: 'Charges per started hour. Weekend and event pricing are new types, not new if-branches in the lot (open/closed principle).' },
    { id: 'flat', label: 'FlatPricing', sub: 'implements', x: 1, y: 2, color: 'purple', info: 'A fixed fee per visit. Swapped in through the constructor or functional options.' },
    { id: 'level', label: 'Level', sub: 'free lists by size', x: 3, y: 2, color: 'blue', info: 'Keeps one free list (or min-heap) of spot IDs per size, so finding the smallest fitting spot is O(1) instead of scanning every spot.' },
    { id: 'ticket', label: 'Ticket', sub: 'spot, plate, entry', x: 5, y: 2, color: 'yellow', info: 'A value-like record: ID, plate, spot ID, entry time, and later exit time and fee. It references the spot and vehicle; it does not own them.' },
    { id: 'gate', label: 'EntryGate', sub: 'one per entrance', x: 1, y: 4, color: 'gray', info: 'Several gates call the same ParkingLot concurrently. Gates hold no state of their own about spots.' },
    { id: 'spot', label: 'Spot', sub: 'id, size, vehicle', x: 3, y: 4, color: 'green', info: 'Size is Small, Medium or Large. Holds zero or one vehicle. EV-charging or reserved spots extend it via a field or a type, without changing the lot.' },
    { id: 'vehicle', label: 'Vehicle', sub: 'plate, size', x: 5, y: 4, color: 'green', info: 'Car, Bike or Truck, created by a small factory from the vehicle type. Only its size matters for allocation.' },
  ],
  edges: [
    { from: 'lot', to: 'pricing', label: 'uses' },
    { from: 'hourly', to: 'pricing', dashed: true },
    { from: 'flat', to: 'pricing', dashed: true, label: 'implements' },
    { from: 'lot', to: 'display', label: 'notifies' },
    { from: 'lot', to: 'level', label: '1..* levels' },
    { from: 'level', to: 'spot', label: '1..* spots' },
    { from: 'spot', to: 'vehicle', label: '0..1' },
    { from: 'lot', to: 'ticket', label: 'issues' },
    { from: 'ticket', to: 'spot', label: 'refs' },
    { from: 'ticket', to: 'vehicle', label: 'refs' },
    { from: 'gate', to: 'lot', label: 'Park / Exit' },
  ],
  steps: [
    { caption: 'Structure first: ParkingLot owns Levels, which own Spots (composition: a spot has no meaning outside its level). State this aloud in the interview before writing code.', active: ['lot', 'level', 'spot', 'lot>level', 'level>spot'] },
    { caption: 'A car arrives at a gate, which calls lot.Park(vehicle). The lot takes its mutex: two gates must never get the same spot. This lock is the concurrency point interviewers ask about.', flows: [{ from: 'gate', to: 'lot', label: 'Park(car)' }] },
    { caption: 'The lot asks each level for the smallest free spot that fits a car. The level pops a spot ID from its Medium free list in O(1).', flows: [{ from: 'lot', to: 'level', label: 'find(Medium)' }, { from: 'level', to: 'spot', label: 'pop free list' }] },
    { caption: 'The spot records the vehicle and the lot issues a Ticket that references both. The lock is released and the gate prints the ticket.', flows: [{ from: 'spot', to: 'vehicle', label: 'occupy' }, { from: 'lot', to: 'ticket', label: 'new Ticket' }] },
    { caption: 'Display boards are observers: the lot publishes the new free count and does not know how many boards exist or how they render.', flows: [{ from: 'lot', to: 'display', label: 'free: 41' }] },
    { caption: 'On exit, Exit(ticketID) asks the PricingStrategy for the fee. Hourly or flat pricing is chosen at construction, so a new rule is a new type with no change to the lot (Strategy pattern).', flows: [{ from: 'gate', to: 'lot', label: 'Exit(t-17)' }, { from: 'lot', to: 'pricing', label: 'Fee(ticket)' }], active: ['hourly', 'flat'] },
    { caption: 'The spot is freed and pushed back onto its level\'s free list. Inject a clock and the pricing strategy so tests are deterministic, and test concurrent Park calls with the race detector.', flows: [{ from: 'spot', to: 'level', label: 'push free list' }, { from: 'lot', to: 'display', label: 'free: 42' }] },
  ],
});

