registerDiagram({
  id: 'sd-retry-dlq',
  roadmap: 'system-design', module: 6, problem: 'Retry with backoff and dead-letter queue',
  kind: 'graph',
  title: 'Retry topics and a dead-letter queue: keep the partition moving',
  desc: 'A consumer calls a flaky payment API. Follow one message through in-process retries, delayed retry topics and finally the DLQ, and see why the original partition never stops while the message is parked.',
  nodes: [
    { id: 'prod', label: 'Producer', sub: 'order service', x: 0, y: 0, color: 'gray', info: 'Publishes OrderPaid events keyed by order ID, so all events for one order land in one partition and stay ordered.' },
    { id: 'main', label: 'orders', sub: 'main topic', x: 2, y: 0, shape: 'db', color: 'orange', info: 'The main topic. A message that blocks here blocks every message behind it in the same partition (head-of-line blocking), which is why failures must leave the main topic quickly.' },
    { id: 'cons', label: 'Consumer', sub: 'idempotent handler', x: 4, y: 0, color: 'blue', info: 'Processes a message, commits the offset only after success, and dedupes by event ID because retries and redrives deliver the same message again.' },
    { id: 'api', label: 'Payment API', sub: 'flaky: 503s', x: 6, y: 0, color: 'purple', info: 'A dependency with transient failures (timeouts, 503) and permanent ones (400 invalid card). Only transient failures are worth retrying.' },
    { id: 'r1', label: 'orders.retry.1m', sub: 'delay 1 minute', x: 2, y: 2, shape: 'db', color: 'yellow', info: 'A retry topic whose consumer waits until each message is due (pause the partition, or sleep until timestamp + 1 min). Headers carry the attempt number, first-failure time and last error.' },
    { id: 'r2', label: 'orders.retry.10m', sub: 'delay 10 minutes', x: 4, y: 2, shape: 'db', color: 'yellow', info: 'A longer delay tier. Tiers grow roughly exponentially (1 min, 10 min, 1 h) so a dependency outage is not hammered by retries.' },
    { id: 'dlq', label: 'orders.dlq', sub: 'parked + reason', x: 6, y: 2, shape: 'db', color: 'red', info: 'Messages that exhausted their attempts or failed permanently. Nothing consumes it automatically: it is a holding area for humans and tools.' },
    { id: 'ops', label: 'DLQ tooling', sub: 'alert, redrive', x: 6, y: 4, color: 'teal', info: 'Alert on DLQ depth and age of the oldest message, show the error and payload, and redrive selected messages back to the main topic once the bug or outage is fixed.' },
  ],
  edges: [
    { from: 'prod', to: 'main', label: 'publish' },
    { from: 'main', to: 'cons' },
    { from: 'cons', to: 'api', label: 'charge' },
    { from: 'cons', to: 'r1', both: true, label: 'retry after 1m' },
    { from: 'cons', to: 'r2', both: true, label: 'retry after 10m' },
    { from: 'cons', to: 'dlq', label: 'attempt 4 fails' },
    { from: 'dlq', to: 'ops', label: 'alert on depth' },
  ],
  steps: [
    { caption: 'Happy path: the consumer reads an event, charges the payment API and commits the offset only after the call succeeded. At-least-once delivery means the handler must be idempotent.', flows: [{ from: 'prod', to: 'main', label: 'OrderPaid' }, { from: 'main', to: 'cons' }, { from: 'cons', to: 'api', label: 'charge' }] },
    { caption: 'A transient 503. First try a short in-process retry: 3 attempts in total (2 retries) with jittered backoff of 100 to 400 ms. Blips are absorbed without leaving the consumer.', flows: [{ from: 'api', to: 'cons', label: '503', color: 'red' }, { from: 'cons', to: 'api', label: 'attempt 2, 3' }] },
    { caption: 'Still failing. Do not block the partition for minutes: publish a copy to orders.retry.1m with attempt=2 and the error in headers, then commit the original offset so the messages behind it keep flowing.', flows: [{ from: 'cons', to: 'r1', label: 'attempt=2' }], active: ['main'] },
    { caption: 'The retry consumer waits until the message is due and runs the same handler. It fails again, so the message moves to the 10-minute tier. Ordering for this order ID is now lost; say so in the interview.', flows: [{ from: 'r1', to: 'cons', label: 'due after 1m' }, { from: 'cons', to: 'r2', label: 'attempt=3' }] },
    { caption: 'After the last tier fails, or immediately for a permanent error such as a validation failure, the message goes to the DLQ with the reason. Retrying a permanent error only wastes capacity.', flows: [{ from: 'r2', to: 'cons', label: 'due after 10m' }, { from: 'cons', to: 'dlq', label: 'give up', color: 'red' }] },
    { caption: 'Operators are paged on DLQ depth or age, inspect the payload and fix the cause. Redrive sends the messages back to the main topic; dedup by event ID makes the replay safe. SQS does the same with maxReceiveCount and a redrive policy.', flows: [{ from: 'dlq', to: 'ops', label: 'alert' }, { from: 'ops', to: 'main', label: 'redrive', color: 'green' }] },
  ],
});

registerDiagram({
  id: 'sd-choreography-orchestration',
  roadmap: 'system-design', module: 6, topic: 'Event-Driven Architecture',
  kind: 'graph',
  title: 'Choreography vs orchestration for the same checkout flow',
  desc: 'Top: services react to each other\'s events and nobody is in charge. Bottom: one orchestrator sends commands and owns the workflow state. Step through the happy path and a failure in each style.',
  groups: [
    { id: 'chor', label: 'Choreography: react to events', x: 0, y: 0, w: 6, h: 3, color: 'blue' },
    { id: 'orch', label: 'Orchestration: one coordinator', x: 0, y: 4, w: 6, h: 3, color: 'purple' },
  ],
  nodes: [
    { id: 'ord', label: 'Order service', sub: 'OrderPlaced', x: 0, y: 1, color: 'blue', info: 'Publishes OrderPlaced and moves on. It does not know who reacts, which keeps coupling low but hides the end-to-end flow.' },
    { id: 'bus', label: 'Event bus', sub: 'Kafka topics', x: 2, y: 1, w: 2, shape: 'pill', color: 'orange', info: 'Every service subscribes to the events it cares about. The workflow exists only implicitly, as the sum of all subscriptions.' },
    { id: 'pay', label: 'Payment', sub: 'on OrderPlaced', x: 5, y: 0, color: 'green', info: 'Charges the card when it sees OrderPlaced and publishes PaymentCaptured. It also has to listen for StockFailed to refund: compensation logic lives here.' },
    { id: 'inv', label: 'Inventory', sub: 'on PaymentCaptured', x: 5, y: 1, color: 'green', info: 'Reserves stock when it sees PaymentCaptured and publishes StockReserved or StockFailed.' },
    { id: 'ship', label: 'Shipping', sub: 'on StockReserved', x: 5, y: 2, color: 'green', info: 'Creates a shipment when stock is reserved.' },
    { id: 'ord2', label: 'Order service', sub: 'starts the saga', x: 0, y: 5, color: 'purple', info: 'Starts a workflow instance per order and reads its status from the orchestrator.' },
    { id: 'orc', label: 'Saga orchestrator', sub: 'Temporal / Step Functions', x: 2, y: 5, w: 2, color: 'purple', info: 'Owns the workflow: which step is next, timeouts, retries and compensations. Its state is persisted after every step, so a crash resumes the saga instead of losing it.' },
    { id: 'pay2', label: 'Payment', sub: 'Charge / Refund', x: 5, y: 4, color: 'green', info: 'Exposes commands (Charge, Refund) and replies. It no longer needs to know about inventory at all.' },
    { id: 'inv2', label: 'Inventory', sub: 'Reserve / Release', x: 5, y: 5, color: 'green', info: 'Exposes Reserve and Release commands. Each command handler is idempotent because the orchestrator retries.' },
    { id: 'ship2', label: 'Shipping', sub: 'CreateShipment', x: 5, y: 6, color: 'green', info: 'The last step, retried until it succeeds: after payment and stock the saga only moves forward.' },
  ],
  edges: [
    { from: 'ord', to: 'bus', label: 'OrderPlaced' },
    { from: 'bus', to: 'pay', both: true },
    { from: 'bus', to: 'inv', both: true },
    { from: 'bus', to: 'ship', both: true },
    { from: 'ord2', to: 'orc', label: 'start saga' },
    { from: 'orc', to: 'pay2', both: true },
    { from: 'orc', to: 'inv2', both: true },
    { from: 'orc', to: 'ship2', both: true },
  ],
  steps: [
    { caption: 'Choreography: the order service publishes OrderPlaced, a fact in the past tense. It does not call anyone and does not wait.', flows: [{ from: 'ord', to: 'bus', label: 'OrderPlaced' }], active: ['chor'] },
    { caption: 'Payment reacts and publishes PaymentCaptured; inventory reacts to that and publishes StockReserved; shipping reacts to that. Each service is simple and loosely coupled.', flows: [{ from: 'bus', to: 'pay', label: 'OrderPlaced' }, { from: 'pay', to: 'bus', label: 'PaymentCaptured' }, { from: 'bus', to: 'inv' }] },
    { caption: 'Failure: inventory publishes StockFailed. Payment must also subscribe to StockFailed and refund. Compensations are scattered, the flow is visible only in traces, and adding a step means editing several services.', flows: [{ from: 'inv', to: 'bus', label: 'StockFailed', color: 'red' }, { from: 'bus', to: 'pay', label: 'refund?', color: 'red' }] },
    { caption: 'Orchestration: the order service starts a saga. The orchestrator sends commands (Charge, then Reserve, then CreateShipment) and waits for each reply, persisting progress after every step.', flows: [{ from: 'ord2', to: 'orc', label: 'start saga' }, { from: 'orc', to: 'pay2', label: 'Charge' }, { from: 'pay2', to: 'orc', label: 'ok' }], active: ['orch'] },
    { caption: 'Failure: Reserve fails. The orchestrator runs the compensation in one place (Refund) and marks the order failed. Timeouts, retries and the current state of every order are explicit and queryable.', flows: [{ from: 'orc', to: 'inv2', label: 'Reserve' }, { from: 'inv2', to: 'orc', label: 'out of stock', color: 'red' }, { from: 'orc', to: 'pay2', label: 'Refund', color: 'orange' }] },
    { caption: 'Rule of thumb: choreography for simple fan-out with two or three independent reactions; orchestration for four or more steps, timeouts and compensations. Keep business rules in the services so the orchestrator does not become a god service.', active: ['orc', 'bus'] },
  ],
});

// ----- Module 7: Microservices ---------------------------------------------------

registerDiagram({
  id: 'sd-retry-amplification',
  roadmap: 'system-design', module: 7, problem: 'Prevent retry storms in a deep call chain',
  kind: 'graph',
  title: 'Retry amplification: 3 retries per layer means 64x at the bottom',
  desc: 'A request passes A, B and C before reaching D. When D slows down, every layer retries and the attempts multiply. Count them step by step, see why 3 retries is 4 attempts, then apply the fixes.',
  nodes: [
    { id: 'a', label: 'Service A', sub: 'edge / BFF', x: 0, y: 1, color: 'blue', info: 'The layer closest to the user. If any layer retries, it is usually this one (or the client), because it knows the user-facing deadline.' },
    { id: 'b', label: 'Service B', sub: 'retries 3 times', x: 2, y: 1, color: 'blue', info: 'With a policy of 3 retries, B makes up to 4 attempts per incoming call: the original call plus 3 retries.' },
    { id: 'c', label: 'Service C', sub: 'retries 3 times', x: 4, y: 1, color: 'blue', info: 'Also up to 4 attempts per incoming call. Every one of B\'s attempts triggers a full round of C\'s attempts.' },
    { id: 'd', label: 'Service D', sub: 'slow, overloaded', x: 6, y: 1, shape: 'db', color: 'red', info: 'The struggling dependency. Every retry from above lands here, at the exact moment it has the least capacity to spare.' },
    { id: 'budget', label: 'Retry budget', sub: 'retries <= 10%', x: 2, y: 3, color: 'green', enter: 5, info: 'A per-client token bucket: each successful call adds a fraction of a token, each retry spends one. During an outage the bucket empties and retries stop, capping extra load at about 10%.' },
    { id: 'breaker', label: 'Circuit breaker', sub: 'open: fail fast', x: 4, y: 3, color: 'orange', enter: 6, info: 'Once D\'s error rate crosses the threshold, C stops calling it for a cool-down period and returns a fallback, giving D room to recover.' },
  ],
  edges: [
    { from: 'a', to: 'b', label: '1 call' },
    { from: 'b', to: 'c', label: 'up to 4 attempts' },
    { from: 'c', to: 'd', label: 'up to 4 per call' },
  ],
  steps: [
    { caption: 'Normal day: one user request is one call at every hop. A calls B, B calls C, C calls D.', flows: [{ from: 'a', to: 'b', label: '1' }, { from: 'b', to: 'c', label: '1' }, { from: 'c', to: 'd', label: '1' }] },
    { caption: 'D starts timing out. C retries 3 times: 1 original call plus 3 retries is 4 attempts. D now sees 4 calls per request.', flows: [{ from: 'c', to: 'd', label: '4 attempts', color: 'orange' }], active: ['d'] },
    { caption: 'B also retries 3 times. Each of B\'s 4 attempts makes C try 4 times: 4 x 4 = 16 calls at D for one user request.', flows: [{ from: 'b', to: 'c', label: '4 attempts', color: 'orange' }, { from: 'c', to: 'd', label: '16 calls', color: 'red' }] },
    { caption: 'If A retries 3 times too, D sees 4 x 4 x 4 = 64 calls per user request. Amplification = attempts per layer to the power of layers. Only if "3" means 3 total attempts is it 3 x 3 x 3 = 27.', flows: [{ from: 'a', to: 'b', label: '4 attempts', color: 'orange' }, { from: 'b', to: 'c', label: '16', color: 'orange' }, { from: 'c', to: 'd', label: '64 calls', color: 'red' }] },
    { caption: 'Fix 1: retry at one layer only, usually the edge, with exponential backoff and full jitter. Fix 2: a retry budget caps retries at about 10% of calls, so an outage cannot multiply load.', flows: [{ from: 'a', to: 'b', label: 'retries here only' }, { from: 'c', to: 'd', label: '1 per attempt' }], active: ['budget'] },
    { caption: 'Fix 3: propagate deadlines so D stops work nobody waits for, and a circuit breaker at C fails fast. Fix 4: D sheds load with 503 and Retry-After, and callers treat overload errors as non-retryable.', flows: [{ from: 'd', to: 'c', label: '503 Retry-After', color: 'red' }, { from: 'c', to: 'b', label: 'fast fallback' }], active: ['breaker'] },
  ],
});

registerDiagram({
  id: 'sd-strangler-fig',
  roadmap: 'system-design', module: 7, problem: 'Migrate a monolith with the strangler fig pattern',
  kind: 'graph',
  title: 'Strangler fig: carve a service out of a monolith, reversibly',
  desc: 'Put a routing facade in front of the monolith, build the new service beside it, sync its data with CDC, shadow and canary the traffic, then flip data ownership. Every step can be rolled back.',
  nodes: [
    { id: 'clients', label: 'Clients', icon: '📱', x: 0, y: 2, color: 'gray', info: 'Web, mobile and partner clients. They never notice the migration: URLs and contracts stay the same.' },
    { id: 'facade', label: 'Routing facade', sub: 'gateway, % rules', x: 2, y: 2, color: 'teal', info: 'An API gateway or proxy that routes by path and percentage. Installing it first, with 100% to the monolith, changes nothing and gives you the lever for every later step.' },
    { id: 'mono', label: 'Monolith', sub: 'all features today', x: 4, y: 1, color: 'blue', info: 'Keeps serving everything that has not been migrated. The notification code inside it is deleted only at the very end.' },
    { id: 'monodb', label: 'Monolith DB', sub: 'shared schema', x: 6, y: 1, shape: 'db', color: 'green', info: 'The shared database. The new service must not read these tables directly in the end state, otherwise you have built a distributed monolith.' },
    { id: 'newsvc', label: 'Notifications svc', sub: 'new, own DB', x: 4, y: 3, color: 'purple', enter: 2, info: 'The first seam: a capability with clear boundaries and a different scaling profile. It has its own data model and database.' },
    { id: 'newdb', label: 'Notifications DB', sub: 'owned by new svc', x: 6, y: 3, shape: 'db', color: 'green', enter: 2, info: 'Backfilled from a snapshot, then kept in sync by CDC through an anti-corruption layer that translates the old model into the new one.' },
  ],
  edges: [
    { from: 'clients', to: 'facade' },
    { from: 'facade', to: 'mono', label: '100% → 0%' },
    { from: 'facade', to: 'newsvc', label: '0% → 100%' },
    { from: 'mono', to: 'monodb' },
    { from: 'newsvc', to: 'newdb' },
    { from: 'monodb', to: 'newdb', label: 'CDC + translate' },
  ],
  steps: [
    { caption: 'Step 0: put a routing facade in front of the monolith with 100% of traffic going to it. Nothing changes for users, but every later move becomes a routing rule.', flows: [{ from: 'clients', to: 'facade', label: 'request' }, { from: 'facade', to: 'mono', label: '100%' }] },
    { caption: 'Pick a seam with clear boundaries and real value (here notifications). Build the new service with its own database; backfill it, then stream changes with CDC through an anti-corruption layer.', flows: [{ from: 'monodb', to: 'newdb', label: 'backfill + CDC' }], active: ['newsvc'] },
    { caption: 'Shadow traffic: the facade mirrors requests to the new service and compares its responses with the monolith\'s, but only the monolith\'s answer is returned. Fix differences before any user depends on the new code.', flows: [{ from: 'facade', to: 'mono', label: 'serve' }, { from: 'facade', to: 'newsvc', label: 'shadow copy' }] },
    { caption: 'Canary: route 5%, then 25%, 50% and 100% of notification traffic to the new service, with automatic rollback if its SLOs burn. Rolling back is one routing change.', flows: [{ from: 'facade', to: 'newsvc', label: '5% canary', color: 'orange' }, { from: 'facade', to: 'mono', label: '95%' }] },
    { caption: 'Flip data ownership: the new service becomes the writer of notification data. Stop the CDC from the monolith; if the monolith still needs the data, it calls the new API or reads a replicated view.', flows: [{ from: 'facade', to: 'newsvc', label: '100%' }, { from: 'newsvc', to: 'newdb', label: 'writes' }] },
    { caption: 'Delete the dead notification code and tables from the monolith, then repeat with the next seam. The monolith shrinks until it disappears or becomes just another service.', active: ['mono', 'monodb'] },
  ],
});

