registerDiagram({
  id: 'sd-dr-spectrum',
  roadmap: 'system-design', module: 8, topic: 'Disaster Recovery: RTO, RPO & Strategies',
  kind: 'graph',
  title: 'Disaster recovery spectrum: what runs in the DR region, and what it buys',
  desc: 'Four strategies from cheapest to most expensive. For each, see what is copied out of the primary region, what is already running in the DR region, and the RPO and RTO that follow.',
  groups: [
    { id: 'dr', label: 'DR region', x: 0, y: 4, w: 7, h: 1, color: 'gray' },
  ],
  nodes: [
    { id: 'prim', label: 'Primary region', sub: 'app + database', x: 2, y: 0, w: 3, color: 'blue', info: 'Production. The questions are how much of its recent data you can afford to lose (RPO) and how long you can be down (RTO) if the whole region is gone.' },
    { id: 'backup', label: 'Backup & restore', sub: 'RPO hours, RTO hours', x: 0, y: 2, color: 'green', info: 'Snapshots plus WAL archiving copied to another region. Cheapest. Restoring 6 TB at about 400 MB/s takes over 4 hours before replay and cutover.' },
    { id: 'pilot', label: 'Pilot light', sub: 'RPO min, RTO ~30 min', x: 2, y: 2, color: 'teal', info: 'Data is replicated continuously, but app servers are off or at zero. Infrastructure as code starts them during a disaster.' },
    { id: 'warm', label: 'Warm standby', sub: 'RPO sec, RTO minutes', x: 4, y: 2, color: 'orange', info: 'A scaled-down but fully working copy runs all the time. Failover means scale up, promote the replica and switch traffic.' },
    { id: 'aa', label: 'Active-active', sub: 'RPO ~0, RTO ~0', x: 6, y: 2, color: 'red', info: 'Both regions serve production traffic. Near-zero RPO needs synchronous or consensus replication (paying cross-region latency on writes) or data partitioned by home region.' },
    { id: 'snap', label: 'Snapshots only', sub: 'object storage', x: 0, y: 4, shape: 'db', color: 'gray', info: 'Immutable, versioned backups in a separate account protect against ransomware and mistakes, which replication would faithfully copy.' },
    { id: 'repl', label: 'Replica DB', sub: 'app scaled to zero', x: 2, y: 4, shape: 'db', color: 'gray', info: 'Only the data tier runs. Its lag is your RPO.' },
    { id: 'small', label: 'Small full stack', sub: 'e.g. 10% capacity', x: 4, y: 4, color: 'gray', info: 'Already deployed and tested by synthetic traffic, so failover is mostly scaling and routing.' },
    { id: 'full', label: 'Full stack', sub: 'serving users', x: 6, y: 4, color: 'gray', info: 'Full capacity in every region (N+1), so losing one region does not overload the others.' },
  ],
  edges: [
    { from: 'prim', to: 'backup' }, { from: 'prim', to: 'pilot' }, { from: 'prim', to: 'warm' }, { from: 'prim', to: 'aa' },
    { from: 'backup', to: 'snap' }, { from: 'pilot', to: 'repl' }, { from: 'warm', to: 'small' }, { from: 'aa', to: 'full', both: true },
  ],
  steps: [
    { caption: 'Two numbers drive the choice. RPO: how much recent data may be lost, which decides how data is replicated. RTO: how long recovery may take, which decides how much is already running elsewhere.', active: ['prim'] },
    { caption: 'Backup and restore: snapshots and archived WAL are copied to the DR region. RPO is the backup interval (minutes with WAL archiving), RTO is hours because terabytes must be restored first.', flows: [{ from: 'prim', to: 'backup', label: 'snapshot + WAL' }, { from: 'backup', to: 'snap' }] },
    { caption: 'Pilot light: the database replicates continuously but the application is switched off. RPO is replication lag; RTO is the time to start the app tier from infrastructure as code, tens of minutes.', flows: [{ from: 'prim', to: 'pilot', label: 'async replication' }, { from: 'pilot', to: 'repl' }] },
    { caption: 'Warm standby: a small but complete copy is always running. Failover is scale up, promote the replica, switch DNS or the global load balancer: minutes. Fence the old primary to avoid split brain.', flows: [{ from: 'prim', to: 'warm', label: 'replication' }, { from: 'warm', to: 'small', label: 'scale up' }] },
    { caption: 'Active-active: both regions serve users, so failover is just routing away from the failed region in seconds. Cost roughly doubles, and data needs conflict-free design or synchronous consensus.', flows: [{ from: 'prim', to: 'aa', label: 'both serve' }, { from: 'aa', to: 'full' }] },
    { caption: 'Replication is not backup: a bad migration or a DELETE replicates everywhere in seconds. Every tier still needs point-in-time recovery and immutable backups, and restores must be tested against the RTO.', flows: [{ from: 'prim', to: 'pilot', label: 'bad DELETE', color: 'red' }], active: ['backup', 'snap'] },
    { caption: 'Choose per system, not per company: analytics on backup and restore, catalog on pilot light or warm standby, the payment ledger on warm standby or active-active. Prove it with DR drills.', active: ['backup', 'pilot', 'warm', 'aa'] },
  ],
});

