registerDiagram({
  id: 'sd-snowflake-layout',
  roadmap: 'system-design', module: 9, topic: 'Unique ID Generation: Snowflake, UUIDv7 and Friends',
  kind: 'graph',
  title: 'Snowflake ID: 64 bits of time, worker and sequence',
  desc: 'The bit layout on top, the generator below. See where each field comes from, how two IDs in the same millisecond stay unique, what goes wrong when the clock moves backwards, and why time-ordered IDs keep B-tree inserts cheap.',
  groups: [
    { id: 'bits', label: '64-bit signed integer (BIGINT)', x: 0, y: 0, w: 7, h: 1, color: 'gray' },
  ],
  nodes: [
    { id: 'sign', label: 'Sign', sub: '1 bit, always 0', x: 0, y: 0, color: 'gray', info: 'Kept at zero so IDs are positive in signed 64-bit types such as Java long or SQL BIGINT.' },
    { id: 'ts', label: 'Timestamp', sub: '41 bits: ms since a custom epoch (~69 years)', x: 1, y: 0, w: 3, color: 'blue', info: '2^41 ms is about 69.7 years from a custom epoch (2024-01-01 in the example code). Because time is in the high bits, sorting IDs sorts by creation time to the millisecond.' },
    { id: 'worker', label: 'Worker ID', sub: '10 bits: 1,024 workers', x: 4, y: 0, w: 2, color: 'purple', info: 'Often split into 5 datacenter bits and 5 machine bits. Must be unique among live generators, otherwise two workers produce identical IDs.' },
    { id: 'seq', label: 'Sequence', sub: '12 bits: 4,096/ms', x: 6, y: 0, color: 'orange', info: 'A counter within one millisecond on one worker: up to 4,096 IDs per ms, about 4M IDs per second per worker.' },
    { id: 'clock', label: 'Clock', sub: 'UnixMilli()', x: 0, y: 2, color: 'teal', info: 'Wall clock synchronised by NTP or chrony. It can jump backwards after a sync, which is the classic Snowflake failure mode.' },
    { id: 'gen', label: 'Generator', sub: 'mutex: lastMs, seq', x: 2, y: 2, w: 2, color: 'blue', info: 'An in-process library: no network hop per ID. A mutex protects lastMs and the sequence.' },
    { id: 'etcd', label: 'etcd lease', sub: 'assigns worker ID', x: 5, y: 2, color: 'purple', info: 'Workers claim an ID with a lease (or use a StatefulSet ordinal). If the lease is lost the generator must stop, or an ID could be reused while another worker holds it.' },
    { id: 'id', label: 'ID', sub: '(ts<<22) | (w<<12) | seq', x: 2, y: 4, w: 2, color: 'green', info: 'Shift each field into place and OR them together. A 64-bit integer fits a BIGINT column, compresses well and needs no string handling.' },
    { id: 'db', label: 'B-tree index', sub: 'appends on the right', x: 5, y: 4, shape: 'db', color: 'green', info: 'Increasing keys land in the right-most leaf page, so inserts are sequential and pages stay full. Random UUIDv4 keys scatter inserts over the whole tree and cause page splits.' },
  ],
  edges: [
    { from: 'clock', to: 'gen', label: 'now (ms)' },
    { from: 'etcd', to: 'gen', label: 'worker 7' },
    { from: 'gen', to: 'id', label: 'compose' },
    { from: 'id', to: 'db', label: 'INSERT' },
  ],
  steps: [
    { caption: 'The layout: 1 sign bit, 41 bits of milliseconds, 10 bits of worker ID and 12 bits of sequence. Time sits in the high bits, so numeric order is creation order.', active: ['bits', 'sign', 'ts', 'worker', 'seq'] },
    { caption: 'The timestamp counts milliseconds since a custom epoch. 41 bits last about 69 years, and starting from a recent epoch instead of 1970 keeps all of them available.', flows: [{ from: 'clock', to: 'gen', label: 'now = 1,203,4xx' }], active: ['ts'] },
    { caption: 'The worker ID makes concurrent generators disjoint. Assign it with an etcd or ZooKeeper lease or a StatefulSet ordinal. Two workers with the same ID will eventually produce duplicate IDs.', flows: [{ from: 'etcd', to: 'gen', label: 'worker 7' }], active: ['worker'] },
    { caption: 'Within one millisecond the sequence counts 0, 1, 2 and so on. At 4,096 it wraps, and the generator spins until the next millisecond rather than reuse a value.', active: ['seq', 'gen'] },
    { caption: 'Compose the ID with shifts and OR. No network call, no coordination per ID: millions of IDs per second per process, roughly sortable across the whole fleet.', flows: [{ from: 'gen', to: 'id', label: 'shift + OR' }] },
    { caption: 'Failure mode: NTP steps the clock back 5 ms. Reusing those milliseconds could repeat IDs, so the generator refuses (or waits until it catches up) and alerts. Monitor clock offset on every host.', flows: [{ from: 'clock', to: 'gen', label: 'now - 5 ms', color: 'red' }], active: ['clock'] },
    { caption: 'Stored as a primary key, increasing IDs append to the right of the B-tree. UUIDv7 gives the same property with 48 bits of ms plus random bits and zero coordination, at 128 bits.', flows: [{ from: 'id', to: 'db', label: 'INSERT' }] },
  ],
});

registerDiagram({
  id: 'sd-geohash-cells',
  roadmap: 'system-design', module: 9, topic: 'Geo-Indexing: Geohash, Quadtree, S2 and H3',
  kind: 'graph',
  title: 'Geohash cells: why "nearby" means the cell plus its 8 neighbours',
  desc: 'Nine real precision-6 geohash cells around downtown San Francisco. A driver 120 m away sits in a different cell with a different prefix. See how the 3x3 search, an exact distance filter and Redis GEO solve it.',
  groups: [
    { id: 'area', label: 'Search area: cell + 8 neighbours', x: 0, y: 1, w: 3, h: 3, color: 'teal' },
  ],
  nodes: [
    { id: 'nw', label: '9q8yyj', x: 0, y: 1, color: 'gray', info: 'North-west neighbour. Each precision-6 cell here is about 0.6 km tall and 1 km wide; cell width shrinks toward the poles.' },
    { id: 'n', label: '9q8yym', x: 1, y: 1, color: 'gray', info: 'North neighbour.' },
    { id: 'ne', label: '9q8yyt', x: 2, y: 1, color: 'gray', info: 'North-east neighbour.' },
    { id: 'w', label: '9q8yyh', x: 0, y: 2, color: 'gray', info: 'West neighbour.' },
    { id: 'c', label: '9q8yyk', sub: 'rider is here', x: 1, y: 2, color: 'blue', info: 'The rider\'s cell. Geohash interleaves longitude and latitude bits and encodes them in base32, so a longer shared prefix means a smaller shared cell.' },
    { id: 'e', label: '9q8yys', sub: 'driver 120 m away', x: 2, y: 2, color: 'orange', info: 'Just across the eastern border. Its prefix differs from the rider\'s cell, so a prefix-only query on 9q8yyk misses this nearby driver.' },
    { id: 'sw', label: '9q8yy5', x: 0, y: 3, color: 'gray', info: 'South-west neighbour.' },
    { id: 's', label: '9q8yy7', x: 1, y: 3, color: 'gray', info: 'South neighbour.' },
    { id: 'se', label: '9q8yye', x: 2, y: 3, color: 'gray', info: 'South-east neighbour.' },
    { id: 'redis', label: 'Redis GEO', sub: 'ZSET, geohash score', x: 4, y: 1, shape: 'db', color: 'red', info: 'GEOADD stores members in a sorted set scored by a 52-bit geohash. GEOSEARCH computes the covering cells, scans their score ranges and filters by exact distance for you.' },
    { id: 'drivers', label: 'Driver apps', icon: '🚗', sub: 'location every 4 s', x: 6, y: 1, color: 'gray', info: 'Only the latest position matters for matching, so each update overwrites the previous one. Location history goes to a stream for analytics.' },
    { id: 'svc', label: 'Search service', sub: 'filter, rank by ETA', x: 4, y: 3, color: 'blue', info: 'Turns the candidate set into an answer: exact haversine distance, availability, then ranking by road ETA from the routing service.' },
  ],
  edges: [
    { from: 'drivers', to: 'redis', label: 'GEOADD every 4 s' },
    { from: 'svc', to: 'redis', label: 'GEOSEARCH 2 km' },
  ],
  steps: [
    { caption: 'Geohash turns a point into a short string by interleaving longitude and latitude bits. Points that share a prefix share a cell; at precision 6 a cell is roughly 1 km by 0.6 km here.', active: ['c'] },
    { caption: 'A naive "nearby" query looks up only the rider\'s cell prefix 9q8yyk. It is cheap: a single prefix or range scan in any sorted index.', flows: [{ from: 'svc', to: 'c', label: 'prefix 9q8yyk' }] },
    { caption: 'The bug: a driver 120 m east is in 9q8yys, a different prefix. Two points can be metres apart yet share no prefix at all, so prefix-only search misses close candidates at every cell edge.', active: ['e'] },
    { caption: 'The fix: query the rider\'s cell and its 8 neighbours. Nine range scans are still cheap, and any point within one cell-width of the rider is guaranteed to be inside the search area.', active: ['area', 'nw', 'n', 'ne', 'w', 'c', 'e', 'sw', 's', 'se'] },
    { caption: 'The 3x3 block only reaches about one cell-width around the rider, so pick a precision whose cells are at least the search radius (6 for ~500 m, 5 for 2 km). Then filter candidates by exact haversine distance and rank by ETA.', flows: [{ from: 'e', to: 'svc', label: 'candidates' }, { from: 'c', to: 'svc', label: 'candidates' }] },
    { caption: 'In practice Redis GEO does the cell math: drivers GEOADD their position every few seconds, and GEOSEARCH BYRADIUS returns sorted matches. Shard the key per city to spread load.', flows: [{ from: 'drivers', to: 'redis', label: 'GEOADD' }, { from: 'svc', to: 'redis', label: 'GEOSEARCH' }] },
    { caption: 'Alternatives: a quadtree adapts cell size to density (small cells downtown, big ones in suburbs); H3 hexagons have six equidistant neighbours, which makes k-ring searches and per-cell surge pricing cleaner.', active: ['redis', 'svc'] },
  ],
});

registerDiagram({
  id: 'sd-search-indexing',
  roadmap: 'system-design', module: 9, topic: 'Search: Inverted Indexes, Ranking & the Indexing Pipeline',
  kind: 'graph',
  title: 'Search: from database row to ranked results',
  desc: 'The write path feeds a derived index from CDC; the read path analyzes the query, scatters it to every shard, intersects postings lists, scores with BM25 and merges the top hits. Finish with a zero-downtime reindex.',
  nodes: [
    { id: 'db', label: 'Catalog DB', sub: 'source of truth', x: 0, y: 0, shape: 'db', color: 'green', info: 'Products live here with transactions and constraints. The search index is a derived, rebuildable view of this data, never the other way round.' },
    { id: 'kafka', label: 'Kafka', sub: 'CDC, key = id', x: 2, y: 0, shape: 'db', color: 'orange', info: 'Debezium or an outbox relay publishes every change keyed by product ID, so updates to one product stay ordered.' },
    { id: 'indexer', label: 'Indexer', sub: 'analyze, bulk upsert', x: 4, y: 0, color: 'purple', info: 'Enriches documents (price, stock, popularity), then writes them with the bulk API using the source version as an external version, so replays cannot overwrite newer data.' },
    { id: 'alias', label: 'Alias products', sub: '→ products_v17', x: 6, y: 0, color: 'teal', info: 'Clients and the query service only know the alias. A reindex builds products_v18 in the background and flips the alias atomically.' },
    { id: 's1', label: 'Shard 1', sub: 'segments + postings', x: 3, y: 2, shape: 'db', color: 'blue', info: 'Each shard holds whole documents (document partitioning) in immutable Lucene segments, merged in the background like LSM compaction. Replicas add throughput and availability.' },
    { id: 's2', label: 'Shard 2', sub: 'segments + postings', x: 5, y: 2, shape: 'db', color: 'blue', info: 'Same structure for a different subset of documents. A query must ask every shard, because any of them may hold matches.' },
    { id: 'postings', label: 'Inverted index', sub: 'red → 1, 3, 9 ...', x: 6, y: 4, color: 'yellow', info: 'Term to postings list: sorted document IDs with term frequency and positions, delta-compressed. AND queries intersect lists starting from the rarest term; positions support phrase queries.' },
    { id: 'user', label: 'User', icon: '🔎', sub: '"red running shoes"', x: 0, y: 4, color: 'gray', info: 'Types a free-text query plus filters such as size and price range.' },
    { id: 'qsvc', label: 'Query service', sub: 'merge + rerank', x: 2, y: 4, color: 'blue', info: 'Runs the same analyzer as indexing, builds a query with scoring text clauses and cached filter clauses, scatters to shards, merges their top-K, and re-ranks the best few hundred with business signals.' },
  ],
  edges: [
    { from: 'db', to: 'kafka', label: 'CDC' },
    { from: 'kafka', to: 'indexer' },
    { from: 'indexer', to: 's1' },
    { from: 'indexer', to: 's2' },
    { from: 'user', to: 'qsvc', label: 'query' },
    { from: 'qsvc', to: 's1', both: true },
    { from: 'qsvc', to: 's2', both: true },
  ],
  steps: [
    { caption: 'Write path: a product changes in the database, the source of truth. CDC publishes the change to Kafka keyed by product ID.', flows: [{ from: 'db', to: 'kafka', label: 'row changed' }, { from: 'kafka', to: 'indexer' }] },
    { caption: 'The indexer analyzes text (tokenize, lowercase, stem, synonyms) and bulk-upserts the document with an external version. The document is routed to one shard by hash of its ID.', flows: [{ from: 'indexer', to: 's1', label: 'doc 3' }, { from: 'indexer', to: 's2', label: 'doc 9' }] },
    { caption: 'Each shard adds terms to its inverted index in a new immutable segment. A refresh every second makes it searchable: near-real-time, not read-your-writes.', active: ['s1', 's2', 'postings'] },
    { caption: 'Read path: the query is analyzed with the same analyzer into terms red, run, shoe, then sent to every shard (scatter).', flows: [{ from: 'user', to: 'qsvc', label: 'red running shoes' }, { from: 'qsvc', to: 's1', label: 'terms' }, { from: 'qsvc', to: 's2', label: 'terms' }] },
    { caption: 'Each shard intersects the postings lists, scores matches with BM25 (term frequency, rarity, document length) and returns only its local top 50.', flows: [{ from: 's1', to: 'qsvc', label: 'top 50' }, { from: 's2', to: 'qsvc', label: 'top 50' }], active: ['postings'] },
    { caption: 'The query service merges the shard results (gather), re-ranks the best few hundred with popularity, stock and conversion signals, and returns a page with a search_after cursor.', flows: [{ from: 'qsvc', to: 'user', label: 'ranked page' }] },
    { caption: 'Changing an analyzer or mapping needs a reindex: build products_v18 from a snapshot while dual-writing live changes, compare, then flip the alias atomically. No downtime, and rollback is another flip.', flows: [{ from: 'indexer', to: 'alias', label: 'flip to v18' }] },
  ],
});

registerDiagram({
  id: 'sd-typeahead',
  roadmap: 'system-design', module: 9, problem: 'Design typeahead / search autocomplete',
  kind: 'graph',
  title: 'Typeahead: precomputed top-K tries online, aggregation offline',
  desc: 'The online path answers each keystroke from caches and an in-memory trie in milliseconds. The offline path turns query logs into decayed popularity scores and ships versioned trie snapshots, with a trending overlay for freshness.',
  nodes: [
    { id: 'user', label: 'Browser', icon: '⌨️', sub: 'debounce ~150 ms', x: 0, y: 0, color: 'gray', info: 'Debouncing and a local cache of recent prefixes cut requests several-fold. The client also cancels in-flight requests for stale prefixes.' },
    { id: 'cdn', label: 'CDN', sub: 'short prefixes', x: 2, y: 0, color: 'teal', info: 'One- and two-letter prefixes are the hottest and the same for everyone (unless personalised), so they cache well at the edge for a few minutes.' },
    { id: 'svc', label: 'Suggest service', sub: 'trie in memory', x: 4, y: 0, color: 'blue', info: 'Holds a trie snapshot in RAM, sharded by prefix range sized from measured traffic (not by first letter, which is skewed). Lookup cost depends on prefix length, not on dataset size.' },
    { id: 'trend', label: 'Trending overlay', sub: 'last 15 min counts', x: 6, y: 0, shape: 'db', color: 'red', info: 'A small Redis structure updated from the stream with recent counts, so breaking terms appear within minutes instead of waiting for the next snapshot.' },
    { id: 'logs', label: 'Query logs', sub: 'Kafka', x: 0, y: 2, shape: 'db', color: 'orange', info: 'Submitted searches (not every keystroke) with timestamp, locale and result clicks.' },
    { id: 'agg', label: 'Aggregation', sub: 'Flink / Spark', x: 2, y: 2, color: 'purple', info: 'Counts queries with time decay, e.g. score = sum of count x exp(-age / tau), removes offensive or rare terms and normalises spelling and case.' },
    { id: 'build', label: 'Trie builder', sub: 'top-K per node', x: 4, y: 2, color: 'purple', info: 'Builds the trie and stores the top K (5 to 10) completions at every node, so a lookup never walks the subtree. Compress single-child chains (radix tree) to save memory.' },
    { id: 'store', label: 'Snapshot store', sub: 'S3, versioned', x: 6, y: 2, shape: 'db', color: 'green', info: 'Versioned snapshots allow blue/green loading and instant rollback if a bad build ships.' },
    { id: 'node', label: 'Trie node "ca"', sub: 'cat, car, camera ...', x: 2, y: 4, color: 'yellow', info: 'Example node: children keyed by next character plus a precomputed list such as [cat 9.1, car 8.7, camera 7.2, cake 6.9, canada 6.5].' },
  ],
  edges: [
    { from: 'user', to: 'cdn', label: 'GET /suggest?q=ca' },
    { from: 'cdn', to: 'svc', label: 'miss' },
    { from: 'trend', to: 'svc', label: 'merge' },
    { from: 'user', to: 'logs', label: 'submitted query' },
    { from: 'logs', to: 'agg' },
    { from: 'agg', to: 'build', label: 'scores' },
    { from: 'build', to: 'store', label: 'snapshot v42' },
    { from: 'store', to: 'svc', label: 'blue/green load' },
    { from: 'build', to: 'node', dashed: true },
  ],
  steps: [
    { caption: 'The user types "ca". The client waits about 150 ms of silence before asking, checks its own cache, then calls GET /suggest?q=ca. At ~7K QPS average, debouncing matters.', flows: [{ from: 'user', to: 'cdn', label: 'q=ca' }] },
    { caption: 'Short prefixes are the hottest and identical for most users, so the CDN answers many of them directly with a TTL of a few minutes.', flows: [{ from: 'cdn', to: 'user', label: 'cached top 10', color: 'green' }] },
    { caption: 'On a miss the suggest service walks the trie to node "ca" and returns its precomputed top-K: cost proportional to the prefix length, typically well under a millisecond.', flows: [{ from: 'cdn', to: 'svc', label: 'miss' }, { from: 'svc', to: 'cdn', label: 'top 10' }], active: ['node'] },
    { caption: 'A trending overlay from the last 15 minutes is merged in, so a breaking news term appears quickly. Blocklists filter offensive suggestions at both stages.', flows: [{ from: 'trend', to: 'svc', label: 'fresh terms' }] },
    { caption: 'Offline path: submitted queries go to Kafka, and an aggregation job computes popularity with time decay, so last week counts more than last year.', flows: [{ from: 'user', to: 'logs', label: 'submitted query' }, { from: 'logs', to: 'agg' }] },
    { caption: 'The builder creates a new trie with top-K at every node and writes a versioned snapshot. Precomputing top-K trades memory and build time for constant-time reads.', flows: [{ from: 'agg', to: 'build', label: 'scores' }, { from: 'build', to: 'store', label: 'v42' }] },
    { caption: 'Servers load the new snapshot side by side and switch atomically (blue/green); a bad build is rolled back by pointing at v41. Base freshness is hours, the overlay covers minutes.', flows: [{ from: 'store', to: 'svc', label: 'load v42' }] },
  ],
});

registerDiagram({
  id: 'sd-notification-system',
  roadmap: 'system-design', module: 9, problem: 'Design a notification system',
  kind: 'graph',
  title: 'Notification system: dedupe, check preferences, queue by priority',
  desc: 'An event becomes a push, SMS or email. Follow it through idempotent intake, preference and rate checks, priority queues that keep OTPs fast during a marketing blast, channel workers, providers and delivery tracking.',
  nodes: [
    { id: 'src', label: 'Product services', sub: 'orders, social, ads', x: 0, y: 1, color: 'gray', info: 'Callers send intent (user, event type, params), not rendered messages. Templates and channels are the notification system\'s job.' },
    { id: 'api', label: 'Notification API', sub: 'idempotency key', x: 2, y: 1, color: 'blue', info: 'Validates, deduplicates by idempotency key (usually the source event ID) and returns 202 Accepted. Everything after this is asynchronous.' },
    { id: 'prefs', label: 'Prefs + caps', sub: 'opt-in, quiet hours', x: 2, y: 3, shape: 'db', color: 'green', info: 'Per user and channel: opt-in or out, quiet hours in the user\'s time zone, frequency caps (e.g. max 3 marketing pushes a day), plus the device token list and locale for templates.' },
    { id: 'sched', label: 'Scheduler', sub: 'send-at, time zones', x: 0, y: 3, color: 'purple', info: 'Holds delayed sends and campaigns. A 50M-user campaign is released gradually (about 14K/s over an hour), not all at once.' },
    { id: 'qh', label: 'Urgent queue', sub: 'OTP, transactional', x: 4, y: 0, shape: 'db', color: 'red', info: 'Separate queues per priority avoid head-of-line blocking: a password-reset code must not wait behind 50M marketing emails.' },
    { id: 'ql', label: 'Bulk queue', sub: 'marketing, digests', x: 4, y: 2, shape: 'db', color: 'orange', info: 'Large and bursty. Consumers are throttled to provider limits and can be paused without affecting transactional traffic.' },
    { id: 'wk', label: 'Channel workers', sub: 'push / SMS / email', x: 6, y: 1, color: 'blue', info: 'One worker pool per channel, each with a token bucket per provider, retries with backoff, a fallback vendor, and a DLQ for messages that keep failing.' },
    { id: 'prov', label: 'Providers', sub: 'APNs, FCM, SMS, mail', x: 6, y: 3, color: 'gray', info: 'Third parties with their own rate limits and outages. Responses and later webhooks report delivered, bounced, unsubscribed or invalid device token.' },
    { id: 'log', label: 'Delivery log', sub: 'status per message', x: 4, y: 4, shape: 'db', color: 'green', info: 'notifications(id, user, channel, template, status, attempts). Feeds user-facing history, support tools and delivery-rate metrics.' },
  ],
  edges: [
    { from: 'src', to: 'api', label: 'notify(user, event)' },
    { from: 'api', to: 'prefs', label: 'check' },
    { from: 'sched', to: 'api', label: 'due sends' },
    { from: 'api', to: 'qh', label: 'OTP' },
    { from: 'api', to: 'ql', label: 'campaign' },
    { from: 'qh', to: 'wk' },
    { from: 'ql', to: 'wk' },
    { from: 'wk', to: 'prov', label: 'send' },
    { from: 'prov', to: 'log', label: 'delivery webhook' },
  ],
  steps: [
    { caption: 'The order service asks to notify user 42 that an order shipped, with the event ID as idempotency key. A retried call with the same key is acknowledged without sending twice.', flows: [{ from: 'src', to: 'api', label: 'OrderShipped' }] },
    { caption: 'Check preferences and caps: is the user opted in for this channel, inside quiet hours, over the daily cap? Then render the template in the user\'s locale and pick device tokens.', flows: [{ from: 'api', to: 'prefs', label: 'opt-in? caps?' }, { from: 'prefs', to: 'api', label: 'push, en-GB' }] },
    { caption: 'Route by priority: transactional messages such as OTPs go to the high-priority queue, campaigns to the bulk queue. A marketing burst can never delay a login code.', flows: [{ from: 'api', to: 'qh', label: 'OTP' }, { from: 'api', to: 'ql', label: 'campaign' }] },
    { caption: 'Channel workers consume both queues with weights, respect each provider\'s rate limit with a token bucket, retry transient errors with backoff and fail over to a second SMS or email vendor.', flows: [{ from: 'qh', to: 'wk', label: 'first' }, { from: 'ql', to: 'wk', label: 'throttled' }, { from: 'wk', to: 'prov', label: 'send' }] },
    { caption: 'Providers report delivered, bounced or invalid-token, immediately or by webhook. The log is updated idempotently; invalid tokens are pruned so they are not retried forever.', flows: [{ from: 'prov', to: 'log', label: 'delivered' }] },
    { caption: 'Scheduled and campaign sends come from the scheduler, released gradually and per time zone so 9 am local means 9 am for everyone, and the system sees a smooth 14K/s instead of a spike.', flows: [{ from: 'sched', to: 'api', label: 'due batch' }] },
    { caption: 'Guarantees: at-least-once delivery with dedup by (notification ID, channel), a DLQ per channel, and SLIs such as OTP send latency p99 and delivery rate per provider.', active: ['qh', 'wk', 'log'] },
  ],
});

registerDiagram({
  id: 'sd-web-crawler',
  roadmap: 'system-design', module: 9, problem: 'Design a web crawler',
  kind: 'graph',
  title: 'Web crawler: frontier, politeness, fetch, parse, dedupe, repeat',
  desc: 'The crawl loop of a Mercator-style crawler. Follow URLs from the prioritised frontier through per-host politeness queues, fetchers and the parser, then through content and URL dedup back into the frontier.',
  nodes: [
    { id: 'seeds', label: 'Seed URLs', x: 0, y: 0, color: 'gray', info: 'Starting points: popular domains, sitemaps, previously known URLs due for a recrawl.' },
    { id: 'front', label: 'Frontier', sub: 'priority queues', x: 2, y: 0, color: 'blue', info: 'Front queues by priority: PageRank-like importance, how often the page changes, how long since the last crawl. Higher priority queues are drained more often.' },
    { id: 'back', label: 'Per-host queues', sub: 'politeness', x: 2, y: 2, color: 'blue', info: 'Back queues: one per host, each with a next-allowed-fetch time from robots.txt crawl-delay or a default (about 1 request per second per host). A heap of hosts by next time picks the next due host.' },
    { id: 'dns', label: 'DNS cache', sub: 'local resolver', x: 4, y: 0, color: 'teal', info: 'DNS lookups would otherwise dominate fetch latency at hundreds of pages per second; cache aggressively and resolve asynchronously.' },
    { id: 'fetch', label: 'Fetchers', sub: 'async HTTP, timeouts', x: 4, y: 2, color: 'purple', info: 'Thousands of concurrent connections per node, strict timeouts and size limits, robots.txt checked and cached per host, conditional GETs (ETag) for recrawls.' },
    { id: 'store', label: 'Page store', sub: 'S3 + metadata', x: 6, y: 0, shape: 'db', color: 'green', info: 'Compressed raw pages in object storage for the indexer; metadata (URL hash, fetch time, status, checksum) in a KV store.' },
    { id: 'parse', label: 'Parser', sub: 'links + text', x: 6, y: 2, color: 'purple', info: 'Extracts text and outgoing links, resolves relative URLs and normalises them (lowercase host, strip fragments and tracking parameters) so duplicates look identical.' },
    { id: 'seen', label: 'Seen-URL filter', sub: 'Bloom + KV', x: 4, y: 4, color: 'orange', info: 'A Bloom filter answers "definitely new" cheaply: 1B URLs at 1% false positives need about 1.2 GB. A false positive skips a new URL, which is acceptable; a KV store holds the exact set.' },
    { id: 'dedup', label: 'Content dedup', sub: 'SimHash / checksum', x: 6, y: 4, color: 'orange', info: 'Exact checksums catch identical pages; SimHash catches near-duplicates such as mirrors and pages that differ only in ads or timestamps. Duplicates are stored once and not re-expanded.' },
  ],
  edges: [
    { from: 'seeds', to: 'front', label: 'enqueue' },
    { from: 'front', to: 'back', label: 'route by host' },
    { from: 'back', to: 'fetch', label: 'due URL' },
    { from: 'fetch', to: 'dns', label: 'resolve' },
    { from: 'fetch', to: 'parse', label: 'HTML' },
    { from: 'parse', to: 'store', label: 'raw page' },
    { from: 'parse', to: 'dedup', label: 'fingerprint' },
    { from: 'parse', to: 'seen', label: 'new links' },
    { from: 'seen', to: 'front', label: 'unseen URLs' },
  ],
  steps: [
    { caption: 'Seed URLs enter the frontier. Front queues order work by priority, so important and frequently changing pages are fetched first and recrawled more often.', flows: [{ from: 'seeds', to: 'front', label: 'seeds' }] },
    { caption: 'URLs move to per-host back queues. Each host is fetched at most about once per second, as robots.txt allows. Partitioning hosts across crawler nodes keeps this state local to one node.', flows: [{ from: 'front', to: 'back', label: 'by host' }] },
    { caption: 'A fetcher takes the next due URL, resolves the host through a local DNS cache and downloads with tight timeouts and a size cap. About 400 pages/s gives 1B pages a month.', flows: [{ from: 'back', to: 'fetch', label: 'due URL' }, { from: 'fetch', to: 'dns', label: 'resolve' }] },
    { caption: 'The parser stores the compressed page for the indexer and extracts text and links.', flows: [{ from: 'fetch', to: 'parse', label: 'HTML' }, { from: 'parse', to: 'store', label: 'raw page' }] },
    { caption: 'Content dedup: a checksum or SimHash identical or close to a known page marks a mirror or duplicate, which is not expanded again. This saves both storage and crawl budget.', flows: [{ from: 'parse', to: 'dedup', label: 'SimHash' }] },
    { caption: 'Extracted links are normalised and checked against the seen-URL Bloom filter. Only definitely-new URLs go back into the frontier, closing the loop.', flows: [{ from: 'parse', to: 'seen', label: 'links' }, { from: 'seen', to: 'front', label: 'unseen URLs' }] },
    { caption: 'Spider traps (infinite calendars, session IDs in URLs) are capped by URL length, path depth and a per-host page budget. Recrawl frequency adapts to how often each page actually changed.', active: ['seen', 'back'] },
  ],
});

registerDiagram({
  id: 'sd-dynamo-kv',
  roadmap: 'system-design', module: 9, problem: 'Design a distributed key-value store (Dynamo-style)',
  kind: 'graph',
  title: 'Dynamo-style KV store: ring, quorums, hinted handoff, repair',
  desc: 'Six nodes on a consistent-hash ring with N=3, W=2, R=2. Follow a write while one replica is down, a read that repairs a stale copy, conflicting versions with vector clocks, and background anti-entropy.',
  nodes: [
    { id: 'key', label: 'key cart:42', sub: 'hash → token', x: 0, y: 0, color: 'yellow', info: 'The key is hashed (e.g. MD5 or Murmur3) onto the ring. It belongs to the first node clockwise from its token; real systems give each node many virtual tokens.' },
    { id: 'A', label: 'Node A', sub: 'coordinator', x: 3, y: 0, color: 'blue', info: 'First node clockwise from the key, so it heads the preference list A, B, C. Any node can coordinate a request; it forwards to the replicas.' },
    { id: 'B', label: 'Node B', sub: 'replica 2', x: 5, y: 1, color: 'blue', info: 'Second replica. Replicas are chosen as the next distinct physical nodes, placed in different availability zones.' },
    { id: 'C', label: 'Node C', sub: 'replica 3', x: 5, y: 3, color: 'blue', info: 'Third replica.' },
    { id: 'D', label: 'Node D', sub: 'hint holder', x: 3, y: 4, color: 'gray', info: 'Not a replica for this key, but next on the ring after C. During B\'s outage it stores B\'s copy with a hint and hands it back when B returns (sloppy quorum).' },
    { id: 'E', label: 'Node E', x: 1, y: 3, color: 'gray', info: 'Owns other key ranges. Membership and failure detection spread by gossip with a phi-accrual detector.' },
    { id: 'F', label: 'Node F', x: 1, y: 1, color: 'gray', info: 'Owns the range just before the key\'s token.' },
    { id: 'client', label: 'Client', icon: '💻', x: 3, y: 2, color: 'gray', info: 'Talks to any node, or computes the preference list itself with a ring-aware client library to save a hop.' },
  ],
  edges: [
    { from: 'key', to: 'A', label: 'hash(k) → token' },
    { from: 'A', to: 'B' }, { from: 'B', to: 'C' }, { from: 'C', to: 'D' },
    { from: 'D', to: 'E' }, { from: 'E', to: 'F' }, { from: 'F', to: 'A' },
    { from: 'client', to: 'A', both: true },
  ],
  steps: [
    { caption: 'The key hashes to a token just before A, so its preference list is A, B, C (N = 3). Adding or removing a node moves only the neighbouring range of keys.', flows: [{ from: 'key', to: 'A', label: 'token' }], active: ['A', 'B', 'C'] },
    { caption: 'put(cart:42): A writes locally and forwards to B and C. With W = 2 it acknowledges as soon as two replicas confirm, so one slow node does not slow the write.', flows: [{ from: 'client', to: 'A', label: 'put' }, { from: 'A', to: 'B', label: 'replicate' }, { from: 'A', to: 'C', label: 'replicate' }] },
    { caption: 'B is down (gossip marks it suspect). To stay writable, A sends B\'s copy to D with a hint: a sloppy quorum. When B recovers, D hands the data over and deletes it (hinted handoff).', flows: [{ from: 'A', to: 'D', label: 'copy + hint for B', color: 'orange' }, { from: 'D', to: 'B', label: 'handoff later' }], active: ['B'] },
    { caption: 'Two clients update the cart concurrently on different replicas. Vector clocks show neither version descends from the other, so both siblings are kept and returned; the app merges (union of items) or uses last-writer-wins.', flows: [{ from: 'A', to: 'client', label: 'two siblings', color: 'red' }] },
    { caption: 'get(cart:42) with R = 2: A asks B and C. C returns an older version, so A returns the newest and writes it back to C (read repair). R + W > N means every read overlaps the latest write set.', flows: [{ from: 'A', to: 'C', label: 'read' }, { from: 'C', to: 'A', label: 'stale v3' }, { from: 'A', to: 'C', label: 'repair v4', color: 'green' }] },
    { caption: 'Rarely read keys are fixed by anti-entropy: replicas compare Merkle trees of each key range and transfer only the subtrees whose hashes differ.', flows: [{ from: 'B', to: 'C', label: 'Merkle diff' }] },
    { caption: 'Each node stores data in an LSM engine (commit log, memtable, SSTables with bloom filters). Deletes are tombstones kept long enough for every replica to learn them, then compacted away.', active: ['A', 'B', 'C', 'D', 'E', 'F'] },
  ],
});

registerDiagram({
  id: 'sd-job-scheduler',
  roadmap: 'system-design', module: 9, problem: 'Design a distributed job scheduler',
  kind: 'graph',
  title: 'Distributed job scheduler: partitioned timelines, leased runs',
  desc: 'Jobs are stored by due time, scheduler instances own time-bucket partitions through leases, due runs go to priority queues, and workers execute them at least once with heartbeats. No single leader, no single point of failure.',
  nodes: [
    { id: 'tenants', label: 'Tenants', icon: '👥', x: 0, y: 0, color: 'gray', info: 'Create one-off and cron jobs through the API; each tenant has quotas on jobs and concurrent runs.' },
    { id: 'api', label: 'Job API', sub: 'create, cancel, cron', x: 2, y: 0, color: 'blue', info: 'Validates the schedule, computes next_run_at (in the job\'s time zone for cron) and stores the job.' },
    { id: 'jobs', label: 'Jobs DB', sub: 'next_run_at buckets', x: 4, y: 0, shape: 'db', color: 'green', info: 'jobs(job_id, tenant, schedule, payload, next_run_at, status, version), partitioned so each scheduler can load only its buckets of due jobs.' },
    { id: 'etcd', label: 'etcd', sub: 'partition leases', x: 6, y: 0, shape: 'db', color: 'purple', info: 'Each scheduler instance holds a lease on a set of bucket partitions. If it dies, the lease expires and another instance takes those buckets over.' },
    { id: 's1', label: 'Scheduler 1', sub: 'buckets 0-31', x: 4, y: 2, color: 'blue', info: 'Loads jobs due in the next minute from its buckets into an in-memory timing wheel and fires them within about a second of their time.' },
    { id: 's2', label: 'Scheduler 2', sub: 'buckets 32-63', x: 6, y: 2, color: 'blue', info: 'Same role for other buckets. Adding instances spreads buckets; there is no single leader to fail.' },
    { id: 'queue', label: 'Run queues', sub: 'per priority', x: 4, y: 4, shape: 'db', color: 'orange', info: 'Runs are enqueued with a run ID of (job_id, scheduled_for). Separate priorities and per-tenant fairness keep one tenant\'s burst from starving others.' },
    { id: 'workers', label: 'Workers', sub: 'lease + heartbeat', x: 2, y: 4, color: 'purple', info: 'Take a lease on a run, heartbeat while working and extend the lease for long jobs. A crashed worker stops heartbeating, the lease expires and the run is re-queued.' },
    { id: 'runs', label: 'job_runs', sub: 'unique(job, time)', x: 0, y: 4, shape: 'db', color: 'green', info: 'One row per run with status, attempts and result. The unique key makes duplicate enqueues and retries harmless.' },
  ],
  edges: [
    { from: 'tenants', to: 'api', label: 'POST /jobs' },
    { from: 'api', to: 'jobs', label: 'INSERT' },
    { from: 'etcd', to: 's2', label: 'lease buckets 32-63' },
    { from: 'jobs', to: 's1', label: 'load next minute' },
    { from: 's1', to: 'queue', label: 'enqueue due run' },
    { from: 's2', to: 'queue' },
    { from: 'queue', to: 'workers', label: 'pull' },
    { from: 'workers', to: 'runs', label: 'result' },
  ],
  steps: [
    { caption: 'A tenant creates a cron job. The API computes the next run time and stores the job in the bucket for that time. Nothing runs yet; the database is the durable timeline.', flows: [{ from: 'tenants', to: 'api', label: 'POST /jobs' }, { from: 'api', to: 'jobs', label: 'next_run_at' }] },
    { caption: 'Scheduler instances divide the buckets between them with leases in etcd. No single leader: losing an instance only pauses its buckets until the lease expires and another takes over.', flows: [{ from: 'etcd', to: 's2', label: 'lease' }, { from: 'etcd', to: 's1', label: 'lease' }] },
    { caption: 'Each scheduler loads the next minute of due jobs from its buckets into an in-memory timing wheel, so firing is precise without polling the database every second.', flows: [{ from: 'jobs', to: 's1', label: 'due in 60 s' }] },
    { caption: 'At the due time the run (job_id, scheduled_for) is enqueued and next_run_at advances to the next cron occurrence. A duplicate enqueue after a failover hits the unique run ID and is ignored.', flows: [{ from: 's1', to: 'queue', label: 'run 17@10:00' }, { from: 's1', to: 'jobs', label: 'next_run_at++' }] },
    { caption: 'A worker pulls the run, takes a lease and heartbeats. If it crashes, the lease expires and the run is retried: execution is at-least-once, so job handlers must be idempotent.', flows: [{ from: 'queue', to: 'workers', label: 'run 17' }] },
    { caption: 'The result is recorded in job_runs. Failures retry with exponential backoff up to a limit, then go to a DLQ and alert the tenant.', flows: [{ from: 'workers', to: 'runs', label: 'SUCCEEDED' }] },
    { caption: 'Midnight herd: 100K jobs due at 00:00. Preload the minute early, add jitter where the tenant allows it, and enforce per-tenant quotas so one tenant cannot fill every worker.', active: ['s1', 's2', 'queue'] },
  ],
});

