registerDiagram({
  id: 'sd-lld-lru',
  roadmap: 'system-design', module: 11, problem: 'LRU cache',
  kind: 'graph',
  title: 'LRU cache: hash map + doubly linked list, O(1) everything',
  desc: 'A capacity-4 LRU cache. The map finds a node in O(1); the list keeps recency order with O(1) unlink and push-front. Step through a Get, a Put that evicts, and the concurrency question that always follows.',
  nodes: [
    { id: 'map', label: 'map[key]*node', sub: 'O(1) lookup', x: 2, y: 0, w: 3, color: 'purple', info: 'Go: map[K]*entry, or container/list with map[K]*list.Element. The map points into the list so a found key can be unlinked without searching.' },
    { id: 'head', label: 'head', sub: 'sentinel', x: 0, y: 2, shape: 'pill', color: 'gray', info: 'Dummy nodes at both ends mean insert and unlink never special-case an empty list or the first and last element.' },
    { id: 'n1', label: 'a', sub: 'most recent', x: 1, y: 2, color: 'blue', info: 'Each node stores key, value, prev and next. The key is stored so eviction can delete the map entry for the tail node.' },
    { id: 'n2', label: 'b', x: 2, y: 2, color: 'blue', info: 'Order from head to tail is most to least recently used.' },
    { id: 'n3', label: 'c', x: 3, y: 2, color: 'blue', info: 'Get(c) moves this node to the front.' },
    { id: 'n4', label: 'd', sub: 'least recent', x: 4, y: 2, color: 'red', info: 'The eviction candidate: tail.prev.' },
    { id: 'tail', label: 'tail', sub: 'sentinel', x: 5, y: 2, shape: 'pill', color: 'gray', info: 'tail.prev is always the least recently used entry.' },
    { id: 'e', label: 'e', sub: 'new entry', x: 1, y: 4, color: 'green', ghost: true, enter: 4, info: 'Inserted at the front after the eviction, and registered in the map.' },
  ],
  edges: [
    { from: 'head', to: 'n1', both: true }, { from: 'n1', to: 'n2', both: true }, { from: 'n2', to: 'n3', both: true },
    { from: 'n3', to: 'n4', both: true }, { from: 'n4', to: 'tail', both: true },
    { from: 'map', to: 'n1', dashed: true }, { from: 'map', to: 'n2', dashed: true }, { from: 'map', to: 'n3', dashed: true }, { from: 'map', to: 'n4', dashed: true },
  ],
  steps: [
    { caption: 'Two structures: a hash map from key to list node, and a doubly linked list ordered from most recent (after head) to least recent (before tail). Capacity is 4 and the cache is full.', active: ['map', 'head', 'n1', 'n2', 'n3', 'n4', 'tail'] },
    { caption: 'Get(c): the map returns c\'s node in O(1). Unlink it by joining its prev and next, then insert it after head. The order is now c, a, b, d. Both pointer changes are O(1).', flows: [{ from: 'map', to: 'n3', label: 'lookup c' }, { from: 'n3', to: 'head', label: 'move to front' }] },
    { caption: 'Put(e) with the cache full: the victim is tail.prev, here d. Unlink it and delete map[d.key]; this is why each node stores its key.', flows: [{ from: 'tail', to: 'n4', label: 'tail.prev' }, { from: 'n4', to: 'map', label: 'delete d', color: 'red' }] },
    { caption: 'Insert e after head and set map[e] to its node. Put on an existing key just updates the value and moves the node to the front. Size never exceeds capacity.', flows: [{ from: 'e', to: 'head', label: 'push front' }, { from: 'map', to: 'e', label: 'map[e]' }] },
    { caption: 'Concurrency: even Get mutates the list, so an RWMutex does not help; use one Mutex. To scale, shard into N independent LRUs by hash(key), or approximate LRU (CLOCK, sampling) like Redis does.', active: ['map', 'n1', 'n2', 'n3', 'n4'] },
  ],
});
